css:
/* Reuse the local usage surfaces, typography and theme tokens. */
.main-shell.local-usage-mode > .content-area { padding-top: 0; }
.main-shell.local-usage-mode > .content-area > .statistics-page,
.remote-main.local-usage-mode > .statistics-page { flex: 1 1 auto; min-height: 0; }
.statistics-page { min-width: 0; display: flex; flex-direction: column; gap: 6px; height: 100%; }
.statistics-navigation { flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.statistics-navigation > b { display: none; }
.statistics-switch { display: flex; align-items: center; gap: 18px; width: 100%; border-bottom: 1px solid var(--line); }
.statistics-switch button { position: relative; min-width: 0; padding: 7px 0 8px; border: 0; background: transparent; color: var(--muted); font-size: 11px; }
.statistics-switch button.active { color: var(--green-deep); font-weight: 600; }
.statistics-switch button.active::after { content: ''; position: absolute; bottom: -1px; left: 0; right: 0; height: 2px; border-radius: 2px; background: var(--green); }
.statistics-switch button:hover { color: var(--ink); }
.statistics-panel { min-height: 0; flex: 1 1 auto; display: flex; flex-direction: column; }
.statistics-panel[hidden] { display: none; }
.statistics-panel > .local-cli-page { flex: 1 1 auto; min-height: 0; }
.global-waste-page { min-width: 0; min-height: 0; height: 100%; display: flex; flex-direction: column; gap: 4px; padding: 8px 12px; overflow-y: auto; font-size: 11px; line-height: 1.35; }
.global-waste-page-head { flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.global-waste-page-head > div:first-child { min-width: 0; display: grid; gap: 2px; }
.global-waste-page-head b { font-size: 13px; }
.global-waste-page-head small { color: var(--ink-soft); font-size: 10px; }
.global-waste-filters { display: flex; gap: 6px; flex: 0 0 auto; }
.global-waste-filters select { max-width: 120px; height: 26px; padding: 0 7px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink-soft); background: var(--control); font-size: 10px; }
.global-waste-state { min-height: 230px; }
.global-waste-summary { flex: 0 0 auto; display: grid; grid-template-columns: minmax(0, 1.8fr) minmax(0, 1fr) minmax(0, .9fr); align-items: center; min-height: 58px; padding: 6px 10px; border: 1px solid var(--line-inner); border-radius: 9px; background: var(--surface-2); }
.global-waste-total { min-width: 0; display: flex; align-items: flex-start; gap: 9px; }
.global-waste-icon { flex: 0 0 auto; width: 29px; height: 29px; display: grid; place-items: center; margin-top: 3px; border-radius: 50%; color: var(--cyan); background: color-mix(in srgb, var(--cyan) 15%, transparent); }
.global-waste-total > div { min-width: 0; }
.global-waste-total small { display: block; color: var(--ink-soft); font-size: 10px; font-weight: 700; }
.global-waste-total > div > div { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 5px; }
.global-waste-total b { font-size: 28px; line-height: 1.15; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
.global-waste-total span:not(.global-waste-icon) { font-size: 9px; }
.global-waste-metric { display: grid; justify-content: center; gap: 4px; padding-left: 7px; border-left: 1px solid var(--line); }
.global-waste-metric small { color: var(--ink-soft); font-size: 10px; }
.global-waste-metric b { font-size: 23px; letter-spacing: -.04em; line-height: 1.3; font-variant-numeric: tabular-nums; }
.global-waste-metric b span { font-size: 12px; }
.global-waste-chart { flex: 0 0 auto; padding: 7px 9px 5px; border: 1px solid var(--line-inner); border-radius: 9px; background: var(--surface-2); --waste-plot-height: 52px; }
.global-waste-block-head { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.global-waste-block-head b { font-size: 12px; }
.global-waste-block-head small { color: var(--ink-soft); font-size: 9px; }
.global-waste-plot { display: grid; grid-template-columns: 25px minmax(0, 1fr); gap: 4px; margin-top: 8px; }
.global-waste-axis { height: calc(var(--waste-plot-height) + 2px); display: flex; flex-direction: column; justify-content: space-between; color: var(--muted); font-size: 8px; text-align: right; line-height: 1; padding-top: 2px; }
.global-waste-bars { position: relative; display: grid; grid-template-columns: repeat(var(--waste-columns), minmax(0, 1fr)); gap: clamp(3px, 1.8vw, 18px); }
.global-waste-gridlines { position: absolute; top: 3px; right: 0; left: 0; height: calc(var(--waste-plot-height) - 3px); display: flex; flex-direction: column; justify-content: space-between; pointer-events: none; }
.global-waste-gridlines i { border-top: 1px dashed var(--line); }
.global-waste-gridlines i:last-child { border-top-style: solid; }
.global-waste-bar-button { position: relative; min-width: 0; display: flex; flex-direction: column; gap: 5px; padding: 0 3px 2px; border: 0; border-radius: 5px; color: var(--ink); background: transparent; text-align: center; }
.global-waste-bar-area { display: flex; align-items: flex-end; justify-content: center; height: var(--waste-plot-height); width: 100%; padding-top: 4px; }
.global-waste-bar { position: relative; display: block; width: 100%; max-width: 124px; min-height: 2px; border-radius: 3px 3px 0 0; background: color-mix(in srgb, var(--cyan) 68%, var(--surface-2)); }
.global-waste-bar b { position: absolute; top: -16px; left: 50%; transform: translateX(-50%); font-size: 10px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.global-waste-bar-button.selected .global-waste-bar { outline: 2px solid color-mix(in srgb, var(--cyan) 70%, var(--ink)); outline-offset: -1px; background: var(--cyan); }
.global-waste-bar-button:hover .global-waste-bar { background: var(--cyan); }
.global-waste-bar-button.unknown .global-waste-bar { background: var(--line); }
.global-waste-bar-button.unknown b { color: var(--faint); }
.global-waste-bar-label { width: 100%; }
.global-waste-bar-label strong { display: flex; justify-content: center; flex-wrap: wrap; color: var(--ink-soft); font-size: 9px; line-height: 1.35; font-weight: 500; font-variant-numeric: tabular-nums; }
.global-waste-bar-label strong span { white-space: nowrap; }
.global-waste-bar-button.selected .global-waste-bar-label strong { color: var(--cyan); font-weight: 700; }
.global-waste-chart-empty { position: absolute; top: 36px; left: 0; right: 0; color: var(--muted); font-size: 11px; text-align: center; pointer-events: none; }
.global-waste-contributions { flex: 1 1 auto; min-height: 164px; display: flex; flex-direction: column; gap: 6px; padding: 8px 9px 0; border: 1px solid var(--line-inner); border-radius: 9px; background: var(--surface-2); overflow: hidden; }
.global-waste-detail-head { flex: 0 0 auto; display: flex; align-items: flex-start; justify-content: space-between; gap: 6px; }
.global-waste-detail-head > div { min-width: 0; display: grid; gap: 2px; }
.global-waste-detail-head b { font-size: 12px; }
.global-waste-detail-head small { color: var(--ink-soft); font-size: 10px; }
.global-waste-detail-head small strong { color: var(--ink); }
.global-waste-detail-head > button { flex: 0 0 auto; padding: 1px 0; border: 0; color: var(--cyan); background: transparent; font-size: 9px; }
.global-waste-accounts-scroll { min-height: 0; flex: 1 1 auto; overflow-y: auto; scrollbar-gutter: stable; scrollbar-width: thin; overscroll-behavior: contain; }
.global-waste-accounts { width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; font-size: 12px; }
.global-waste-accounts th { position: sticky; top: 0; z-index: 1; padding: 5px 6px; color: var(--ink-soft); background: var(--surface-3); font-size: 10px; font-weight: 500; text-align: left; }
.global-waste-accounts th:first-child { width: 51%; border-radius: 5px 0 0 5px; }
.global-waste-accounts th:nth-child(2) { width: 24%; }
.global-waste-accounts th:nth-child(3) { width: 19%; }
.global-waste-accounts th:last-child { width: 6%; padding: 0; border-radius: 0 5px 5px 0; }
.global-waste-accounts .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.global-waste-accounts td { padding: 4px 6px; border-bottom: 1px solid var(--line-inner); vertical-align: middle; font-variant-numeric: tabular-nums; }
.global-waste-accounts td:nth-child(2), .global-waste-accounts td:nth-child(3) { white-space: nowrap; }
.global-waste-accounts td small { color: var(--ink-soft); font-size: 9px; }
.global-waste-accounts td:last-child { padding-right: 1px; padding-left: 0; }
.global-waste-account-toggle { width: 100%; min-width: 0; display: flex; align-items: center; gap: 7px; padding: 0; color: var(--ink); border: 0; background: transparent; text-align: left; }
.global-waste-account-toggle strong { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; font-weight: 500; }
.global-waste-account-toggle .provider-logo { width: 21px; height: 21px; border-radius: 6px; }
.global-waste-expand { width: 19px; height: 20px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 4px; color: var(--muted); background: transparent; }
.global-waste-expand[aria-expanded="true"] svg { transform: rotate(180deg); }
.global-waste-expand:hover, .global-waste-account-toggle:hover { color: var(--cyan); }
.global-waste-accounts .global-waste-cycle-cell { padding: 0 7px 5px; }
.global-waste-cycles { padding: 7px 9px; border-radius: 6px; background: var(--surface-3); }
.global-waste-cycles > small { display: block; margin-bottom: 4px; color: var(--ink-soft); font-size: 9px; }
.global-waste-cycles > div, .global-waste-excluded > div > div { display: flex; align-items: center; justify-content: space-between; gap: 7px; padding: 5px 0; font-size: 9px; }
.global-waste-cycles > div + div, .global-waste-excluded > div > div + div { border-top: 1px solid var(--line); }
.global-waste-cycles > div span, .global-waste-excluded > div > div span { min-width: 0; }
.global-waste-cycles > div small, .global-waste-excluded > div > div small { display: block; margin-top: 2px; color: var(--ink-soft); font-size: 9px; }
.global-waste-cycles > div b, .global-waste-excluded b { flex: 0 0 auto; font-size: 10px; }
.global-waste-cycles .excluded { color: var(--ink-soft); }
.global-waste-accounts .global-waste-empty { padding: 17px 8px; color: var(--muted); font-size: 10px; white-space: normal; text-align: center; }
.global-waste-excluded { flex: 0 0 auto; margin-left: auto; color: var(--ink-soft); font-size: 9px; }
.global-waste-excluded summary { cursor: pointer; }
.global-waste-excluded > div { position: absolute; right: 12px; left: 12px; bottom: 30px; max-height: 150px; overflow: auto; padding: 3px 9px; border: 1px solid var(--line); border-radius: 6px; background: var(--surface); box-shadow: var(--shadow); z-index: 3; }
.global-waste-footnote { position: relative; display: flex; align-items: center; gap: 5px; flex: 0 0 auto; color: var(--ink-soft); font-size: 9px; }
.global-waste-footnote > svg:last-child { margin-left: auto; cursor: help; }
.statistics-page button:focus-visible, .statistics-page select:focus-visible, .global-waste-accounts-scroll:focus-visible, .global-waste-footnote svg:focus-visible { outline: 2px solid var(--focus-border); outline-offset: 2px; }
@media (max-width: 440px) {
  .global-waste-page { padding: 8px; }
  .global-waste-page-head { flex-wrap: wrap; }
  .global-waste-summary { padding: 8px; grid-template-columns: minmax(0, 1.6fr) 1fr .8fr; }
  .global-waste-icon { display: none; }
  .global-waste-total b { font-size: 25px; }
  .global-waste-total span:not(.global-waste-icon) { font-size: 8px; }
  .global-waste-metric b { font-size: 20px; }
  .global-waste-bars { gap: 2px; }
  .global-waste-bar-button { padding-left: 1px; padding-right: 1px; }
  .global-waste-bar-label strong { font-size: 8px; }
}
@media (min-width: 900px) and (min-height: 700px) {
  .statistics-navigation { padding: 2px 4px; }
  .statistics-navigation > b { font-size: 15px; }
  .statistics-switch button { padding: 5px 14px; font-size: 12px; }
  .global-waste-page { padding: 16px 20px; gap: 8px; }
  .global-waste-page-head b { font-size: 15px; }
  .global-waste-page-head small, .global-waste-filters select { font-size: 11px; }
  .global-waste-summary { min-height: 76px; }
  .global-waste-total b { font-size: 36px; }
  .global-waste-total small, .global-waste-total span:not(.global-waste-icon), .global-waste-metric small { font-size: 12px; }
  .global-waste-metric b { font-size: 30px; }
  .global-waste-chart { padding: 12px 15px; --waste-plot-height: clamp(72px, 16vh, 148px); }
  .global-waste-axis { font-size: 10px; }
  .global-waste-bar b { font-size: 12px; top: -20px; }
  .global-waste-bar-label strong { font-size: 10px; }
  .global-waste-block-head b, .global-waste-detail-head b { font-size: 14px; }
  .global-waste-accounts, .global-waste-account-toggle strong { font-size: 13px; }
  .global-waste-accounts td { padding: 7px; }
  .global-waste-accounts th, .global-waste-detail-head small, .global-waste-detail-head > button { font-size: 11px; }
}

@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Noto+Sans+SC:wght@400;500;600;700;800&display=swap');
:root {
  color: var(--ink);
  background: var(--bg);
  font-family: 'Manrope', 'Noto Sans SC', sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  color-scheme: dark;
  --bg: #141d1f; --bg-grad: #1b2629;
  --surface: #1a2527; --surface-2: #202c2e; --surface-3: #263334; --surface-trans: rgba(26, 37, 39, .72);
  --control: #24312f; --control-2: #2b3a39; --knob: #f2f7f4;
  --ink: #e8efeb; --ink-soft: #b6c6c1; --muted: #8ba19b; --faint: #879b95;
  --line: #2c393b; --line-strong: #3d4c4e; --line-inner: #243030; --hover-border: #4d5f60;
  --primary-bg: #dfeae5; --primary-text: #17221f; --primary-bg-hover: #cfe2db;
  --green: #3fb384; --green-deep: #8bd8ac; --green-bg: #1f3930; --green-bg-2: #274537; --green-line: #2c5241;
  --coral: #ef8a70; --coral-deep: #eb9d8b; --coral-bg: #452a22; --coral-bg-2: #59372c; --warn-border: #5c3a2f;
  --chip-bg: #2a3739; --chip-text: #9db1ab;
  --toggle: #3a494b; --backdrop: rgba(4, 10, 10, .55); --backdrop-soft: rgba(4, 10, 10, .45);
  --titlebar-bg: rgba(26, 37, 39, .9); --drawer-bg: rgba(23, 31, 33, .97);
  --shadow: 0 18px 60px rgba(0, 0, 0, .45); --shadow-strong: 0 24px 80px rgba(0, 0, 0, .55);
  --focus-border: #58c494; --focus-ring: rgba(88, 196, 148, .14);
  --meter-track: #2b383a; --meter-off-fill: #6b7d78; --ring-track: #2e3c3e; --score: #6fc79b; --scrollbar: #3d4b4d;
  --widget-bg: #202c2e; --widget-row: #273638; --widget-row-border: rgba(255, 255, 255, .08);
  --widget-text: #edf5f0; --widget-chip: #334647; --widget-chip-label: #9db0ab; --widget-chip-value: #dcf5e2; --widget-chip-sub: #95a6a2;
  --widget-tag-text: #a9c7b9; --widget-tag-bg: #3b5050; --widget-live: #7bd1a0; --widget-live-label: #9eafa9;
  --mint: #d8f2df; --violet: #836fe0; --cyan: #48b9c4; --sky: #4b9ddf; --amber: #e0b45c;
  --onboard-tile: #1c1c1e; --onboard-dash: #444; --onboard-dash-hover: #6d7a7c;
}
:root[data-theme='light'] {
  color-scheme: light;
  --bg: #f3f5f1; --bg-grad: #ffffff;
  --surface: #fbfcf9; --surface-2: #f7faf6; --surface-3: #f0f4ef; --surface-trans: rgba(251, 252, 249, .72);
  --control: #ffffff; --control-2: #f5f8f3; --knob: #ffffff;
  --ink: #1e282d; --ink-soft: #5d6a6e; --muted: #5f6d75; --faint: #66737b;
  --line: #dfe4df; --line-strong: #cfd8d1; --line-inner: #edf0ec; --hover-border: #aab8b0;
  --primary-bg: #1e282d; --primary-text: #ffffff; --primary-bg-hover: #334449;
  --green: #277a59; --green-deep: #2e7756; --green-bg: #e1f2e4; --green-bg-2: #d9efdf; --green-line: #bfe0c8;
  --coral: #e5775e; --coral-deep: #bd665b; --coral-bg: #f9e3dc; --coral-bg-2: #f8e2dc; --warn-border: #efd2cb;
  --chip-bg: #eef1ed; --chip-text: var(--ink-soft);
  --toggle: #dfe5df; --backdrop: rgba(31, 41, 41, .28); --backdrop-soft: rgba(31, 41, 41, .12);
  --titlebar-bg: rgba(251, 252, 249, .9); --drawer-bg: rgba(250, 252, 248, .97);
  --shadow: 0 18px 60px rgba(50, 66, 61, .08); --shadow-strong: 0 24px 80px rgba(42, 58, 52, .2);
  --focus-border: #92bca4; --focus-ring: rgba(112, 171, 130, .12);
  --meter-track: #e8ede8; --meter-off-fill: #adb4b0; --ring-track: #e5ece6; --score: #79bd92; --scrollbar: #ccd6d0;
  --widget-bg: #eef1ec; --widget-row: #ffffff; --widget-row-border: rgba(30, 40, 45, .08);
  --widget-text: #263236; --widget-chip: #e3eae2; --widget-chip-label: #7d8a84; --widget-chip-value: #1e5c3d; --widget-chip-sub: #98a29c;
  --widget-tag-text: #47705c; --widget-tag-bg: #d8e9de; --widget-live: #2e8b66; --widget-live-label: #7d8a84;
  --amber: #a87c24;
  --onboard-tile: #f0f2ef; --onboard-dash: #c9d2ca; --onboard-dash-hover: #9ba69f;
}

* { box-sizing: border-box; }
html, body, #root { min-height: 100%; margin: 0; }
body { min-width: 320px; background: var(--bg); }
button, input, select { font: inherit; }
button { cursor: pointer; }

.app-shell { height: 100vh; display: flex; flex-direction: column; overflow: hidden; color: var(--ink); background: radial-gradient(circle at 50% -25%, var(--bg-grad) 0, var(--bg) 58%); }
.topbar { height: 50px; flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 0 14px; border-bottom: 1px solid var(--line); background: var(--titlebar-bg); backdrop-filter: blur(20px); position: sticky; top: 0; z-index: 5; }
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { width: 30px; height: 30px; border-radius: 9px; background: var(--ink); display: flex; align-items: flex-end; justify-content: center; gap: 3px; padding: 7px; box-shadow: 0 4px 10px rgba(30, 40, 45, .15); }
.brand-mark span { width: 4px; border-radius: 3px; background: #d6f1df; display: block; }
.brand-mark span:nth-child(1) { height: 8px; opacity: .6; }.brand-mark span:nth-child(2) { height: 13px; }.brand-mark span:nth-child(3) { height: 17px; background: #f7a28c; }
.brand strong { display: block; font-size: 14px; letter-spacing: .01em; }.brand small { display: block; margin-top: 2px; color: var(--muted); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; }
.topbar-actions { display: flex; align-items: center; gap: 10px; }.sync-state { display: flex; align-items: center; gap: 7px; color: var(--muted); font-size: 12px; margin-right: 8px; }.sync-state i, .online-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); display: inline-block; box-shadow: 0 0 0 3px rgba(46, 139, 102, .12); }.toolbar-button, .icon-button, .outline-button, .primary-button, .text-button { border: 0; display: inline-flex; align-items: center; justify-content: center; gap: 7px; transition: .18s ease; }.toolbar-button { color: var(--ink-soft); background: transparent; border: 1px solid transparent; padding: 9px 11px; border-radius: 7px; font-size: 12px; }.toolbar-button:hover { border-color: var(--line); background: var(--control); color: var(--ink); }.toolbar-button:disabled { cursor: wait; opacity: .7; }.spinning { animation: spin .8s linear infinite; }@keyframes spin { to { transform: rotate(360deg); } }

.main-shell { width: 100%; max-width: 1680px; margin: 0 auto; padding: 8px clamp(14px, 1.8vw, 30px) 14px; flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; }
.page-heading { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 38px; }.eyebrow { font: 500 10px/1 'DM Mono', monospace; color: var(--faint); letter-spacing: .11em; text-transform: uppercase; }.page-heading h1 { margin: 13px 0 0; font-size: clamp(31px, 4vw, 52px); line-height: 1.13; letter-spacing: -.045em; font-weight: 700; }.page-heading h1 em { font-style: normal; color: var(--faint); }.heading-note { display: flex; align-items: center; gap: 15px; color: var(--muted); font-size: 12px; padding-bottom: 5px; }.tiny-badge { color: var(--green-deep); border-radius: 30px; padding: 7px 11px; background: var(--green-bg); font-weight: 700; }

.view-switcher { display: flex; gap: 5px; border-bottom: 1px solid var(--line); }.view-switcher button { position: relative; display: flex; align-items: center; gap: 9px; background: transparent; border: 0; padding: 14px 17px 16px; color: var(--muted); }.view-switcher button span { font-size: 13px; font-weight: 700; }.view-switcher button small { font-size: 10px; color: var(--faint); margin-left: 3px; }.view-switcher button.active { color: var(--ink); }.view-switcher button.active:after { content: ''; position: absolute; left: 15px; right: 15px; height: 2px; bottom: -1px; border-radius: 2px; background: var(--coral); }.view-switcher button:hover { color: var(--ink); }
