/* 版本更新:标题栏升级徽章与更新弹窗 */
.update-badge { display: inline-flex; align-items: center; gap: 4px; border: 0; border-radius: 9px; padding: 3px 8px; font-size: 10px; font-weight: 700; background: var(--coral); color: #fff; }
