/* Kimi 订阅扫码登录：居中的二维码舞台 + 状态行（过期/失败给操作按钮） */
/* 标题旁问号帮助：气泡经 portal + fixed 渲染在 body 顶层，不受弹窗裁剪、不产生横向溢出 */
.title-help { display: inline-grid; place-items: center; width: 17px; height: 17px; margin-left: 5px; border: 1px solid var(--line); border-radius: 50%; color: var(--muted); cursor: help; vertical-align: -2px; }
.title-help:focus-visible { border-color: var(--focus-border); }
