.drawer-section-title > .title-help:focus-visible { outline: 2px solid var(--focus-border); outline-offset: 2px; }
.title-help-pop { position: fixed; width: 248px; max-height: min(220px, calc(100vh - 16px)); overflow-y: auto; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--line); background: var(--surface); color: var(--muted); font-size: 11px; line-height: 1.65; text-align: left; z-index: 300; box-shadow: var(--shadow-strong); pointer-events: none; animation: fade-in .15s ease-out; }
/* 订阅登录导入弹窗：列表 / 扫码 / 账号设置共用同一个固定尺寸的窗口，切换视图时尺寸不变 */
.import-window { display: flex; flex-direction: column; height: min(420px, calc(100vh - 62px)); min-height: 376px; }
.import-window > .modal-head, .import-window > .modal-actions { flex: 0 0 auto; }
.import-window > .import-grid, .import-window > .kimi-qr-stage, .import-window > .kimi-qr-configure, .import-window > .cli-import-stage, .import-window > .copilot-device-stage, .import-window > .custom-account-scroll { flex: 1 1 auto; min-height: 0; }
.import-window > .modal-actions { margin-top: auto; padding-top: 13px; }
