.kimi-qr-refresh:hover { transform: scale(1.08); }
.kimi-qr-status { color: var(--muted); text-align: center; }
.kimi-qr-status.ok { color: var(--green); }
.kimi-qr-status.fail { color: var(--coral); }
/* 第二步：扫码确认后的账号信息设置（成功横条 + 账号名 / 标签两行） */
.kimi-qr-configure { display: flex; flex-direction: column; justify-content: center; gap: 10px; padding: 6px 0; }
.kimi-qr-ok { display: flex; align-items: center; gap: 11px; padding: 10px 12px; border-radius: 9px; background: var(--green-bg-2); }
.kimi-qr-ok > div { display: grid; gap: 2px; }
.kimi-qr-ok b { font-size: 12px; }
.kimi-qr-ok small { color: var(--muted); font-size: 11px; }
.kimi-qr-done-icon { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%; color: var(--green); background: var(--green-bg); flex: 0 0 auto; }
.kimi-qr-done-icon.duplicate { color: var(--coral-deep); background: var(--coral-bg); }
/* Kimi 磁贴登录方式选择：扫码（含月额度）/ API Key（无月额度）两个大按钮 + 说明 */
.kimi-entry-stage { gap: 9px; }
.kimi-entry-option { display: flex; align-items: center; gap: 12px; padding: 13px 14px; border: 1px solid var(--line); border-radius: 11px; color: var(--ink); background: var(--control); text-align: left; cursor: pointer; transition: border-color .12s ease-out, transform .12s ease-out; }
.kimi-entry-option:hover { border-color: var(--focus-border); transform: translateY(-1px); }
.kimi-entry-icon { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 10px; color: var(--green-deep); background: var(--green-bg); flex: 0 0 auto; }
.kimi-entry-copy { display: grid; gap: 2px; }
.kimi-entry-copy b { font-size: 12px; }
.kimi-entry-copy small { color: var(--muted); font-size: 11px; }
/* Kimi API Key 账号的扫码登录升级卡片（账号编辑弹窗内） */
.kimi-upgrade-card { display: grid; gap: 9px; margin: 2px 0 16px; }
.kimi-upgrade-button { justify-self: start; display: inline-flex; align-items: center; gap: 6px; }
/* GitHub Copilot 设备码登录：大号等宽设备码卡片（点击复制）+ 打开授权页按钮，与扫码页同高 */
.copilot-device-stage { min-height: 236px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding: 6px 0; }
.copilot-code-frame { display: grid; gap: 7px; justify-items: center; padding: 20px 30px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface-2); cursor: pointer; transition: border-color .12s ease-out, transform .12s ease-out; }
.copilot-code-frame:hover { border-color: var(--focus-border); transform: translateY(-1px); }
.copilot-code-frame small { color: var(--faint); font-size: 10px; }
.copilot-code-frame b { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 24px; letter-spacing: 2px; color: var(--ink); }
.copilot-code-frame.stale { opacity: .55; }
.copilot-code-frame.stale b { text-decoration: line-through; }
.copilot-stage-actions { display: flex; align-items: center; justify-content: center; gap: 8px; flex-wrap: wrap; }
.copilot-open-button { flex: 0 0 auto; }
/* 令牌失效后的重新扫码入口：总览卡片的异常图标变成可点按钮，行式视图在「需处理」旁给文字入口 */
.card-status-icon.relogin { border: none; padding: 0; cursor: pointer; transition: transform .12s ease-out; }
.card-status-icon.relogin:hover { transform: scale(1.15); }
.text-button.relogin-link { display: inline-flex; align-items: center; gap: 3px; flex: 0 0 auto; color: var(--coral); font-size: 10px; }
/* 添加账号表单底部：CLI 官方订阅引导脚注（轻量，不打断表单视觉） */
.cli-import-hint { display: flex; align-items: center; gap: 6px; margin: -4px 0 14px; color: var(--faint); font-size: 10px; }
.cli-import-hint .text-button { margin-left: auto; }
/* 厂商弹窗 New API 模板预设 */
.preset-grid { grid-template-columns: auto 1fr; align-items: center; margin: 0 0 14px; }
.preset-hint { color: var(--faint); font-size: 10px; }
/* 额度历史折线图 */
.overview-card.clickable { cursor: pointer; transition: border-color .18s ease; }
.overview-card.clickable:hover { border-color: var(--hover-border); }
.overview-card.clickable.dragging,
.overview-card.clickable.dragging:hover { cursor: grabbing; border-color: var(--hover-border); }
.overview-card.clickable.drag-over,
.overview-card.clickable.drag-over:hover { border-color: var(--focus-border); }
.history-view { gap: 12px; }
.history-view .surface-section { padding-bottom: 4px; }
.history-head { display: flex; align-items: center; gap: 10px; padding: 12px 16px 10px; border-bottom: 1px solid var(--line); }
.history-head .account-identity { flex: 1; min-width: 0; }
.range-control { display: flex; flex: 0 0 auto; gap: 0; }
.range-control button { border: 0; padding: 1px 5px; border-radius: 4px; color: var(--ink-soft); background: transparent; font-size: 9px; }
.range-control button.active { color: var(--ink); background: var(--surface-3); }
.range-control button:hover:not(.active):not(:disabled) { color: var(--ink-soft); }
.range-control button:disabled { opacity: .32; cursor: default; }
.back-button { flex: 0 0 auto; width: 30px; height: 30px; border: 1px solid var(--line); border-radius: 8px; color: var(--ink-soft); background: var(--control); }
.back-button:hover { color: var(--ink); border-color: var(--hover-border); }
/* 趋势/浪费两个视图主体锁成同一固定高度，切换时整个卡片与头部切换按钮都不动；多余空间由图例行（趋势）或滚动区（浪费）吸收 */
.trend-view { height: 271px; display: flex; flex-direction: column; }
.trend-view .chart-legend { margin-top: auto; }
.usage-chart { position: relative; padding: 10px 8px 2px; user-select: none; }
.usage-chart svg { display: block; width: 100%; height: auto; touch-action: pan-y; }
.chart-grid { stroke: var(--line-inner); stroke-width: 1; }
.chart-y-label, .chart-x-label { fill: var(--faint); font-size: 9px; font-family: 'DM Mono', monospace; }
.chart-y-label { text-anchor: end; }
.chart-x-label { text-anchor: middle; }
.chart-cursor { stroke: var(--line-strong); stroke-width: 1; stroke-dasharray: 3 3; }
.chart-cursor.selected { stroke: var(--ink-soft); stroke-width: 1.2; stroke-dasharray: 2 3; }
.chart-detail { display: flex; align-items: center; gap: 4px; min-height: 22px; margin: 0 6px 4px; padding: 3px 6px 3px 8px; border: 1px solid var(--line-inner); border-radius: 7px; background: var(--surface-2); overflow: hidden; white-space: nowrap; }
/* 详情文字窄窗口放不下时横向滑动看全：范围按钮固定在右侧不随滚动；
   滚动条整个隐藏（不做滑动框样式），触屏/鼠标拖动/滚轮平移均可 */
.chart-detail-main { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; overflow-x: auto; overflow-y: hidden; scrollbar-width: none; }
.chart-detail-main::-webkit-scrollbar { display: none; }
/* 浪费视图详情行的内容直接挂在 .chart-detail 下（无 main 包裹），同样支持横向滑动 */
.chart-detail.waste-detail { overflow-x: auto; scrollbar-width: none; }
.chart-detail.waste-detail::-webkit-scrollbar { display: none; }
.chart-detail-main > b { flex: 0 0 auto; color: var(--muted); font-size: 10px; font-weight: 600; }
.chart-detail-item { display: inline-flex; align-items: center; gap: 3px; flex: 0 0 auto; font-size: 10px; color: var(--ink-soft); }
.chart-detail-item b { color: var(--ink); font-weight: 700; }
.chart-detail-item small { color: var(--faint); font-size: 9px; }
.chart-detail-hint { color: var(--ink-soft); font-size: 10px; }
.chart-detail i, .chart-legend i { width: 7px; height: 7px; border-radius: 50%; flex: 0 0 auto; }
.chart-legend { display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 4px 18px 8px; border-top: 1px solid var(--line-inner); }
.chart-legend span { display: inline-flex; align-items: center; gap: 6px; font-size: 10px; color: var(--muted); }
.chart-legend em { font-style: normal; font-weight: 700; color: var(--ink); }
.chart-legend small { font-size: 9px; color: var(--faint); }
.chart-empty { padding: 34px 16px; }

/* 浮窗省略号模式下解除名称块宽度上限：让内容撑满以便检测溢出，标签先于名称被收起 */
.widget-row.ellipsis .widget-account-block { max-width: none; }
/* 名称优先：空间不足时标签先被压缩省略，而不是账号名 */
.account-title-line .tag-pill { flex: 0 4 auto; min-width: 14px; overflow: hidden; text-overflow: ellipsis; }
/* 行式/周期视图的账号行可点击进入趋势图 */
.account-window-row.clickable, .priority-row.clickable { cursor: pointer; }
.usage-chart.zoomed svg { cursor: grab; }
.usage-chart.zoomed svg:active { cursor: grabbing; }
.chart-tools { display: flex; align-items: center; justify-content: space-between; padding: 0 12px 4px; min-height: 18px; }
.chart-hint { color: var(--faint); font-size: 9px; }
.chart-reset { border: 1px solid var(--line); border-radius: 5px; padding: 2px 8px; color: var(--ink-soft); background: var(--control); font-size: 9px; }
.chart-reset:hover { color: var(--ink); border-color: var(--hover-border); }
.chart-legend button { display: inline-flex; align-items: center; gap: 6px; border: 0; padding: 2px 0; color: var(--muted); background: transparent; font-size: 10px; cursor: pointer; }
.chart-legend button:hover { color: var(--ink); }
.chart-legend button.off { opacity: .38; }
.chart-legend button em { font-style: normal; font-weight: 700; color: var(--ink); }

/* 额度浪费统计视图（历史页「浪费」分段）：总高度不超过趋势视图，所有文字单行省略 */
.seg-control { display: flex; flex: 0 0 auto; gap: 2px; padding: 2px; border: 1px solid var(--line); border-radius: 7px; background: var(--control); }
.seg-control button { border: 0; padding: 3px 10px; border-radius: 5px; color: var(--ink-soft); background: transparent; font-size: 10px; }
.seg-control button.active { color: var(--ink); background: var(--surface-3); }
.seg-control button:hover:not(.active) { color: var(--ink-soft); }
.waste-view { height: 271px; display: flex; flex-direction: column; padding: 10px 8px 2px; }
.waste-view > * { flex: 0 0 auto; }
.waste-view > .waste-scroll { flex: 1 1 auto; }
.waste-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 24px; margin: 0 6px 6px; }
.waste-label { font-size: 11px; font-weight: 700; color: var(--muted); white-space: nowrap; }
.waste-stats { display: inline-flex; align-items: center; min-width: 0; font-size: 10px; color: var(--muted); white-space: nowrap; overflow: hidden; }
.waste-stats b { color: var(--amber); font-weight: 700; }
.waste-stats span + span::before { content: '·'; margin: 0 5px; color: var(--faint); }
.waste-detail { display: block; overflow: hidden; text-overflow: ellipsis; font-size: 10px; color: var(--ink-soft); }
.waste-detail > span { margin-right: 12px; }
.waste-detail > span:last-child { margin-right: 0; }
.waste-detail b { color: var(--ink); font-weight: 700; }
.waste-detail .when { color: var(--ink); font-weight: 600; }
.waste-detail .warn { color: var(--amber); }
.waste-scroll { flex: 1 1 auto; min-height: 0; margin: 0 6px; display: flex; flex-direction: column; overflow-x: auto; overflow-y: hidden; scrollbar-width: none; cursor: grab; border: 1px solid var(--line-inner); border-radius: 8px; background: var(--surface-2); user-select: none; }
.waste-scroll::-webkit-scrollbar { display: none; }
.waste-scroll.dragging { cursor: grabbing; }
/* plot 高度 = 柱区（去掉顶部 10px 留白），网格线/平均线的 bottom 百分比都相对柱区 */
.waste-plot { position: relative; flex: 1 1 auto; min-height: 0; margin-top: 10px; min-width: 100%; display: flex; align-items: flex-end; gap: 1px; padding: 0 10px; border-bottom: 1px solid var(--line-inner); }
.waste-gridline { position: absolute; left: 10px; right: 10px; height: 1px; background: var(--line-inner); pointer-events: none; }
.waste-col { flex: 1 0 8px; min-width: 8px; height: 100%; align-self: flex-end; display: flex; align-items: flex-end; }
.waste-plot.mo .waste-col { flex: 1 0 26px; min-width: 26px; }
.waste-bar { width: 100%; max-width: 18px; margin: 0 auto; border-radius: 3px 3px 0 0; min-height: 2px; }
.waste-plot.mo .waste-bar { max-width: 24px; }
.waste-plot.wk .waste-bar { background: linear-gradient(180deg, var(--violet), #6f5ee0); }
.waste-plot.mo .waste-bar { background: linear-gradient(180deg, var(--coral), #d96a62); }
/* 失真（最后观测距重置过远）：斜纹柱，浪费值只是上界 */
.waste-plot.wk .waste-col.bad .waste-bar { background: repeating-linear-gradient(-45deg, color-mix(in srgb, var(--violet) 30%, transparent) 0 3px, transparent 3px 6px); border: 1px solid color-mix(in srgb, var(--violet) 55%, transparent); border-bottom: 0; }
.waste-plot.mo .waste-col.bad .waste-bar { background: repeating-linear-gradient(-45deg, color-mix(in srgb, var(--coral) 30%, transparent) 0 3px, transparent 3px 6px); border: 1px solid color-mix(in srgb, var(--coral) 55%, transparent); border-bottom: 0; }
/* 厂商提前重置：琥珀色点线框，周期不完整不计入统计 */
.waste-col.early .waste-bar { background: color-mix(in srgb, var(--amber) 16%, transparent); border: 1px dotted var(--amber); border-bottom: 0; }
/* 进行中的当前周期：青色虚线框 */
.waste-col.now .waste-bar { background: color-mix(in srgb, var(--cyan) 15%, transparent); border: 1px dashed var(--cyan); border-bottom: 0; }
.waste-col.hot .waste-bar { filter: brightness(1.35); }
.waste-avg { position: absolute; left: 10px; right: 10px; height: 0; border-top: 1px dashed var(--amber); pointer-events: none; }
.waste-avg em { position: absolute; left: 0; top: -9px; padding: 0 4px; color: var(--amber); background: var(--surface-2); font-size: 9px; font-style: normal; }
.waste-empty-hint { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; color: var(--muted); font-size: 11px; text-align: center; pointer-events: none; }
.waste-empty-hint b { color: var(--ink); }
.waste-x-labels { display: flex; flex: 0 0 auto; gap: 1px; min-width: 100%; padding: 3px 10px 2px; }
.waste-x-cell { flex: 1 0 8px; min-width: 8px; overflow: hidden; white-space: nowrap; text-align: center; color: var(--faint); font-size: 8px; line-height: 11px; }
.waste-x-labels.mo .waste-x-cell { flex-basis: 26px; min-width: 26px; }
.waste-legend i { width: 11px; height: 8px; border-radius: 2px; }
.waste-legend i.swatch-early { background: color-mix(in srgb, var(--amber) 16%, transparent); border: 1px dotted var(--amber); }
.waste-legend i.swatch-now { background: color-mix(in srgb, var(--cyan) 15%, transparent); border: 1px dashed var(--cyan); }
.chart-legend .legend-right { margin-left: auto; color: var(--faint); }

/* ── 账号停用 ── */
/* 总览里的停用卡片：档案式展示，整卡沉下去，悬停恢复可读性 */
.overview-card.disabled { opacity: .62; }
.overview-card.disabled:hover { opacity: 1; }
.overview-card.disabled .provider-logo { filter: grayscale(1); }
/* 卡片主体：只有停用时间与停用时长两行静态信息，整体居中 */
.disabled-card-body { align-items: center; flex-direction: column; justify-content: center; gap: 0; padding: 4px 6px; }
.disabled-copy { display: grid; gap: 4px; text-align: center; }
.disabled-copy b { font-size: 13px; }
.disabled-copy small { color: var(--faint); font-size: 10px; }
/* 折叠态：一行文字入口 */
.disabled-fold { display: flex; align-items: center; justify-content: center; gap: 4px; width: 100%; padding: 2px; border: 0; background: none; color: var(--faint); font-size: 10px; cursor: pointer; }
.disabled-fold:hover { color: var(--muted); }
.disabled-fold svg { flex: 0 0 auto; }
/* 历史页头部：账号右侧的内联停用标签（不另起一行） */
.history-disabled-tag { display: inline-flex; align-items: center; gap: 5px; flex: 0 0 auto; color: var(--faint); font-size: 10px; white-space: nowrap; }
/* 设置抽屉的停用账号行与停止/播放开关 */
.settings-account.disabled { opacity: .55; }
.settings-account.disabled:hover { opacity: 1; }
.settings-account.disabled .provider-logo { filter: grayscale(1); }
.status-dot.disabled { background: var(--muted); }
.row-icon-button.stop { color: var(--coral); }
.row-icon-button.stop svg { fill: currentColor; }
.row-icon-button.stop:hover { color: var(--coral-deep); background: var(--coral-bg-2); }
.row-icon-button.play { color: var(--green-deep); }
.row-icon-button.play:hover { background: var(--green-bg); }
/* 浮窗占位：无账号 / 全部停用——沿用 widget-row 卡片，内容整体居中
   占满整条；加号做成圆形徽章（绿色强调），引导双击添加 */
.widget-placeholder { justify-content: center; gap: 7px; color: var(--widget-chip-sub); font-size: 11px; }
.widget-placeholder-icon { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; color: var(--widget-live); background: var(--widget-chip); }
/* 应用内操作确认弹窗（替代系统级 window.confirm）：字号沿用「添加账号」等普通弹窗的规范（标题 18px / 正文 12px / 按钮 11px） */
.confirm-modal .modal-head h2 { font-size: 18px; }
.confirm-modal .confirm-message { margin: 0; color: var(--ink-soft); font-size: 12px; line-height: 1.65; }
/* 小确认框不走表单弹窗的动作区间（23px+17px+分隔线对两行文字的弹窗太大），收紧为紧凑间距 */
.confirm-modal .modal-actions { margin-top: 14px; padding-top: 0; border-top: 0; }
.danger-button { padding: 9px 12px; border: 1px solid transparent; border-radius: 7px; font-size: 11px; font-weight: 700; color: #231009; background: var(--coral); }
.danger-button:hover { background: var(--coral-deep); }
:root[data-theme='light'] .danger-button { color: #fff; }

/* ── 厂商官方账号服务端用量（一比一复刻 DeepSeek 界面演示）── */
/* 三个页签统一 271px 主体；热力图方格按容器宽度自适应（5–14px），近 1 年 53 周完整铺满一屏 */
/* 历史页视图切换下拉：四个入口常驻，不可用项置灰并在项内小字 / 悬停 title 说明原因 */
.history-switch-dismiss { position: fixed; inset: 0; z-index: 48; }
.history-switch-anchor { position: relative; flex: 0 0 auto; }
.history-switch-anchor.open { z-index: 49; }
.history-switch-toggle { display: flex; align-items: center; gap: 4px; padding: 3px 9px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink-soft); background: var(--control); font-size: 10px; }
.history-switch-toggle:hover { color: var(--ink); border-color: var(--hover-border); }
.history-switch-menu { position: absolute; top: calc(100% + 4px); right: 0; z-index: 49; min-width: 90px; padding: 2px; border: 1px solid var(--line); border-radius: 6px; background: var(--surface); box-shadow: 0 8px 24px rgba(20, 40, 30, .14); }
.history-switch-menu button { width: 100%; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 1px 4px; padding: 3px 5px; border: 0; border-radius: 4px; background: transparent; color: var(--ink-soft); font-size: 9px; text-align: left; }
.history-switch-menu button:hover, .history-switch-menu button.active { color: var(--green-deep); background: var(--green-bg); }
.history-switch-menu button.disabled, .history-switch-menu button.disabled:hover { color: var(--faint); background: transparent; cursor: not-allowed; }
.provider-usage-view { height: 271px; min-width: 0; display: flex; flex-direction: column; padding: 7px 12px 5px; }
/* 顶部统计卡片：彩色圆底图标在左，标签 + 数值在右 */
.provider-usage-summary { flex: 0 0 auto; display: flex; gap: 7px; }
.provider-stat { flex: 1 1 0; min-width: 0; display: flex; align-items: center; gap: 7px; padding: 5px 9px; border: 1px solid var(--line-inner); border-radius: 10px; background: var(--surface-2); }
.stat-icon { width: 20px; height: 20px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%; }
.provider-stat .stat-copy { min-width: 0; display: grid; gap: 2px; }
.provider-stat .stat-copy > span { color: var(--ink-soft); font-size: 9px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.provider-stat strong { color: var(--ink); font-size: 12px; line-height: 1.2; font-weight: 700; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* 顶部图标配色（参考图）：花费红闪电 / Token 蓝机器人 / 活跃日绿日历；下方详情行用不同图标避免重复 */
.provider-stat.cost .stat-icon { color: var(--coral); background: var(--coral-bg); }
.provider-stat.tokens .stat-icon { color: var(--sky); background: color-mix(in srgb, var(--sky) 15%, transparent); }
.provider-stat.days .stat-icon { color: var(--green-deep); background: var(--green-bg); }
.provider-stat.plan .stat-icon { color: var(--violet, #7c5cfc); background: color-mix(in srgb, var(--violet, #7c5cfc) 15%, transparent); }
.provider-stat.streak .stat-icon { color: var(--coral); background: var(--coral-bg); }
.provider-stat.peak .stat-icon { color: var(--cyan); background: color-mix(in srgb, var(--cyan) 15%, transparent); }
.provider-stat.longest .stat-icon { color: var(--violet, #7c5cfc); background: color-mix(in srgb, var(--violet, #7c5cfc) 15%, transparent); }
/* 热力图标题行：标题在左，「较少→较多」图例在右 */
.provider-heatmap-head { flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 5px 1px 0; }
.provider-heatmap-title { color: var(--ink-soft); font-size: 10px; font-weight: 700; }
.provider-heatmap-legend { display: flex; align-items: center; gap: 3px; color: var(--faint); font-size: 7px; }
.provider-heatmap-legend .provider-heatmap-cell { width: 7px; height: 7px; }
.provider-heatmap-legend .provider-heatmap-cell.level-1 { background: color-mix(in srgb, var(--cyan) 35%, var(--surface-3)); }
.provider-heatmap-legend .provider-heatmap-cell.level-2 { background: color-mix(in srgb, var(--cyan) 58%, var(--surface-3)); }
.provider-heatmap-legend .provider-heatmap-cell.level-3 { background: color-mix(in srgb, var(--cyan) 82%, var(--surface-3)); }
.provider-heatmap-legend .provider-heatmap-cell.level-4 { background: color-mix(in srgb, var(--cyan) 88%, white 12%); }
/* 热力图外框：接管纵向弹性，滚动容器装在里面；两端渐隐覆盖层提示左右还有更多月份可滑 */
.provider-heatmap-frame { position: relative; flex: 1 1 auto; min-height: 0; display: flex; }
.provider-heatmap-fade { position: absolute; top: 0; bottom: 0; z-index: 1; width: 22px; pointer-events: none; opacity: 0; transition: opacity .15s; }
.provider-heatmap-fade.left { left: 0; background: linear-gradient(90deg, var(--surface-2), transparent); }
.provider-heatmap-fade.right { right: 0; background: linear-gradient(270deg, var(--surface-2), transparent); }
.provider-heatmap-frame.more-left .provider-heatmap-fade.left { opacity: 1; }
.provider-heatmap-frame.more-right .provider-heatmap-fade.right { opacity: 1; }
.provider-heatmap-frame.more-left .provider-heatmap-scroll, .provider-heatmap-frame.more-right .provider-heatmap-scroll { cursor: grab; }
.provider-heatmap-frame.more-left .provider-heatmap-scroll:active, .provider-heatmap-frame.more-right .provider-heatmap-scroll:active { cursor: grabbing; }
.provider-heatmap-scroll { flex: 1 1 auto; min-height: 0; display: flex; align-items: center; overflow-x: auto; overflow-y: hidden; scrollbar-width: none; overscroll-behavior-x: contain; touch-action: pan-x pan-y; padding: 4px 3px; border: 1px solid var(--line-inner); border-radius: 8px; background: var(--surface-2); }
.provider-heatmap-scroll::-webkit-scrollbar { display: none; }
.provider-heatmap-scroll:focus-visible { outline: 2px solid var(--focus-border); outline-offset: -2px; }
.provider-heatmap-board { display: grid; grid-template-columns: 10px auto; grid-template-rows: 11px auto; align-items: flex-start; gap: 3px 7px; width: fit-content; margin: auto; }
.provider-heatmap-corner { grid-column: 1; grid-row: 1; }
.provider-heatmap-months { grid-column: 2; grid-row: 1; position: relative; height: 11px; overflow: visible; color: var(--faint); font-size: 8px; white-space: nowrap; }
.provider-heatmap-weekdays { grid-column: 1; grid-row: 2; width: 10px; display: grid; grid-template-rows: repeat(7, var(--hm-cell-h)); row-gap: var(--hm-gap, 2px); color: var(--faint); font-size: 8px; text-align: center; }
.provider-heatmap-weekdays span { display: grid; place-items: center; }
.provider-heatmap-grid { grid-column: 2; grid-row: 2; display: grid; grid-auto-flow: column; grid-template-rows: repeat(7, var(--hm-cell-h)); grid-auto-columns: var(--hm-cell); gap: var(--hm-gap, 2px); }
/* 方格：GitHub 式圆角小方块，色阶为参考图同款青色系；无数据的日子与空档同色 */
.provider-heatmap-cell { width: 8px; height: 8px; display: block; flex: 0 0 auto; border-radius: 3px; background: var(--surface-3); }
.provider-heatmap-grid button.provider-heatmap-cell { width: var(--hm-cell); height: var(--hm-cell-h); appearance: none; border: 0; padding: 0; border-radius: max(3px, calc(var(--hm-cell) * 0.16)); background: var(--surface-3); }
.provider-heatmap-grid button.provider-heatmap-cell.level-1 { background: color-mix(in srgb, var(--cyan) 35%, var(--surface-3)); }
.provider-heatmap-grid button.provider-heatmap-cell.level-2 { background: color-mix(in srgb, var(--cyan) 58%, var(--surface-3)); }
.provider-heatmap-grid button.provider-heatmap-cell.level-3 { background: color-mix(in srgb, var(--cyan) 82%, var(--surface-3)); }
.provider-heatmap-grid button.provider-heatmap-cell.level-4 { background: color-mix(in srgb, var(--cyan) 88%, white 12%); }
.provider-heatmap-grid button.provider-heatmap-cell.level-missing { background: var(--surface-3); }
.provider-heatmap-grid button.provider-heatmap-cell:hover { box-shadow: 0 0 0 1px var(--ink-soft); }
.provider-heatmap-grid button.provider-heatmap-cell.selected { box-shadow: 0 0 0 2px var(--focus-border); }
.provider-heatmap-grid button.provider-heatmap-cell:focus-visible { outline: 2px solid var(--focus-border); outline-offset: 1px; }
.provider-heatmap-cell.blank { width: var(--hm-cell); height: var(--hm-cell-h); visibility: hidden; }
/* 当日明细：淡青描边卡片，一个卡片内三段纯文字、竖线分隔（参考图无图标）；标签「当日花费」默认显示，切到其他日子换成具体日期 */
.provider-day-card { flex: 0 0 auto; margin: 6px 1px 0; padding: 4px 10px; border: 1px solid color-mix(in srgb, var(--cyan) 30%, var(--line)); border-radius: 10px; background: var(--surface-2); display: grid; grid-template-columns: repeat(3, 1fr); }
.day-cell { min-width: 0; display: flex; align-items: center; padding: 2px 4px; }
.day-cell + .day-cell { border-left: 1px solid var(--line-inner); padding-left: 12px; }
.day-cell > div { min-width: 0; display: grid; gap: 1px; }
.day-cell > div > span { color: var(--muted); font-size: 8px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.day-cell b { min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--ink); font-size: 10px; font-weight: 700; white-space: nowrap; }
.provider-usage-state { height: 271px; display: flex; align-items: center; justify-content: center; gap: 11px; padding: 22px 28px; color: var(--muted); }
.provider-usage-state > svg { flex: 0 0 auto; color: var(--green); }
.provider-usage-state-icon { width: 36px; height: 36px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 10px; color: var(--green-deep); background: var(--green-bg); }
.provider-usage-state > div { min-width: 0; display: grid; gap: 5px; flex: 0 1 auto; max-width: 52em; justify-items: center; text-align: center; }
.provider-usage-state b { color: var(--ink); font-size: 13.5px; }
.provider-usage-state small { color: var(--muted); font-size: 11.5px; line-height: 1.55; }
.provider-usage-state em { color: var(--coral-deep); font-size: 10.5px; font-style: normal; }
.provider-usage-state.auth-required .provider-usage-state-icon { color: var(--coral-deep); background: var(--coral-bg); }
.provider-usage-state.connect-guide .provider-usage-state-icon { color: var(--sky); background: color-mix(in srgb, var(--sky) 15%, transparent); }
.provider-usage-state .outline-button, .provider-usage-state .primary-button { flex: 0 0 auto; padding: 7px 9px; }
.provider-usage-state.connect-guide { flex-direction: column; gap: 0; text-align: center; }
.provider-usage-state.connect-guide .provider-usage-state-icon { margin-bottom: 14px; }
.provider-usage-state.connect-guide > div { flex: 0 0 auto; width: 100%; max-width: 300px; gap: 7px; }
.provider-usage-state.connect-guide .primary-button { min-width: 136px; margin-top: 18px; padding: 8px 14px; }

/* DeepSeek 账号编辑页中的可选连接：状态与余额 API 分开表达，防止用户误以为
   断开官方账号会停止原有额度巡检。 */
.provider-login-option { min-width: 0; margin: 2px 0 10px; padding: 11px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.provider-login-option > span { min-width: 0; }
.provider-login-option b small { margin-left: 4px; color: var(--green-deep); font-size: 8px; font-weight: 500; }
.provider-login-option i { flex: 0 0 auto; }
.provider-login-option { cursor: pointer; }
.provider-login-option input:focus-visible + i { outline: 2px solid var(--focus-border); outline-offset: 2px; box-shadow: 0 0 0 4px var(--focus-ring); }
.provider-connection-card { display: grid; gap: 9px; margin: 12px 0 16px; padding: 11px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); background: transparent; }
.provider-connection-copy { display: flex; align-items: flex-start; gap: 9px; }
.provider-connection-icon { width: 28px; height: 28px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 8px; color: var(--green-deep); background: var(--green-bg); }
.provider-connection-copy > div { min-width: 0; display: grid; gap: 3px; }
.provider-connection-copy b { color: var(--ink); font-size: 11px; }
.provider-connection-copy b em { margin-left: 4px; padding: 1px 5px; border-radius: 7px; color: var(--muted); background: var(--chip-bg); font-size: 8px; font-style: normal; font-weight: 500; }
.provider-connection-copy small { color: var(--faint); font-size: 9px; line-height: 1.45; }
.provider-connection-status { display: flex; align-items: center; gap: 7px; padding: 7px 8px; border: 1px solid var(--line-inner); border-radius: 7px; background: var(--surface); }
.provider-connection-status > i { width: 7px; height: 7px; flex: 0 0 auto; border-radius: 50%; background: var(--faint); }
.provider-connection-status > span { min-width: 0; display: flex; align-items: baseline; gap: 7px; }
.provider-connection-status b { color: var(--ink-soft); font-size: 10px; white-space: nowrap; }
.provider-connection-status small { min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--faint); font-size: 9px; white-space: nowrap; }
.provider-connection-status.connected > i { background: var(--green); box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 13%, transparent); }
.provider-connection-status.connected b { color: var(--green-deep); }
.provider-connection-status.reauth > i { background: var(--coral); box-shadow: 0 0 0 3px color-mix(in srgb, var(--coral) 13%, transparent); }
.provider-connection-status.reauth b { color: var(--coral-deep); }
.provider-connection-actions { display: flex; align-items: center; justify-content: flex-end; gap: 10px; }
.provider-connection-actions .outline-button, .provider-connection-actions .primary-button { padding: 6px 9px; font-size: 10px; }
.provider-connection-actions .text-button.disconnect { color: var(--coral-deep); }
.provider-connection-actions .text-button.disconnect.confirming { padding: 4px 7px; border-radius: 6px; color: var(--coral-deep); background: var(--coral-bg); font-weight: 700; }
.provider-connection-actions button:disabled { cursor: wait; opacity: .62; }
.provider-connection-feedback { display: flex; align-items: flex-start; gap: 5px; padding-top: 7px; border-top: 1px solid var(--line-inner); color: var(--muted); font-size: 9px; line-height: 1.4; }
.provider-connection-feedback svg { flex: 0 0 auto; margin-top: 1px; }
.provider-connection-feedback.ok { color: var(--green-deep); }
.provider-connection-feedback.fail { color: var(--coral-deep); }

.data-transfer-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px; }
.data-transfer-actions .outline-button { min-width: 0; }

.widget-setting-preview { display: none; }
.widget-setting-preview + .outline-button { margin-top: 12px; }

.provider-heatmap-months span { position: absolute; top: 0; line-height: 11px; }

/* ---- 本机 CLI 用量(.local-cli-*;与官方用量页 .provider-usage-* 完全隔离) ---- */
/* 本机用量页需要内部滚动(热力图/模型列表),不给外层 main-shell 留整页滚动 */
.main-shell.local-usage-mode { display: flex; flex-direction: column; overflow: hidden; }
.main-shell.local-usage-mode > .content-area { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.main-shell.local-usage-mode > .content-area > .local-cli-page { flex: 1 1 auto; min-height: 0; }
.local-cli-page { min-width: 0; height: 100%; display: flex; flex-direction: column; padding: 10px 12px; }
.local-cli-page.embedded { height: 271px; padding: 7px 12px 5px; }
.local-usage-tabpanel { min-width: 0; }
.local-cli-page-head { flex: 0 0 auto; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px; margin-bottom: 8px; }
.local-cli-page-title { min-width: 0; display: grid; gap: 1px; }
.local-cli-page-title b { font-size: 13px; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-page-title small { color: var(--faint); font-size: 9px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-page-actions { display: flex; align-items: center; gap: 6px; white-space: nowrap; }
.local-cli-view-switch { flex: 0 0 auto; }
.local-cli-scope-models { min-width: 0; display: flex; align-items: center; gap: 5px; overflow: hidden; color: var(--faint); font-size: 9px; white-space: nowrap; }
.local-cli-scope-models > span:first-child { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--ink-soft); font-weight: 700; }
.local-cli-model-tags { position: relative; flex: 1; min-width: 1em; overflow: hidden; }
.local-cli-model-tags-row { display: flex; align-items: center; gap: inherit; }
.local-cli-model-tags, .local-cli-model-tags-row { column-gap: inherit; }
.local-cli-model-measure { position: absolute; top: 0; left: 0; width: max-content; visibility: hidden; pointer-events: none; }
.local-cli-model-chip { flex: 0 0 auto; max-width: 92px; overflow: hidden; text-overflow: ellipsis; padding: 3px 6px; border: 1px solid var(--line-inner); border-radius: 6px; color: var(--cyan); background: var(--surface-2); font-size: 8px; }
.local-cli-model-more { flex: 0 0 auto; color: var(--muted); font-size: 8px; cursor: help; }
.local-cli-scope-models em { color: var(--faint); font-size: 9px; font-style: normal; }

/* 状态说明卡(首次使用/空态/错误/加载/桌面限制):统一居中垂直布局 */
.local-cli-state-card { flex: 1 1 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; padding: 24px 28px; border: 1px solid var(--line-inner); border-radius: 10px; background: var(--surface-2); color: var(--ink); text-align: center; }
.local-cli-state-card > svg { flex: 0 0 auto; color: var(--cyan); }
.local-cli-state-card.loading > svg { color: var(--ink-soft); }
.local-cli-state-card > div { flex: 0 0 auto; min-width: 0; display: grid; gap: 5px; justify-items: center; }
.local-cli-state-card b { font-size: 13px; letter-spacing: -.01em; }
.local-cli-state-card small { color: var(--muted); font-size: 11.5px; line-height: 1.6; max-width: 42em; }
.local-cli-state-card em { color: var(--coral-deep); font-size: 11px; font-style: normal; }
.local-cli-state-card .outline-button, .local-cli-state-card .primary-button { margin-top: 6px; }
.local-cli-state-icon { width: 38px; height: 38px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 10px; color: var(--green-deep); background: var(--green-bg); }

/* 首次使用说明卡:同样的居中垂直结构,按钮放文字下方 */
.local-cli-intro-card { flex: 1 1 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding: 24px 28px; border: 1px solid var(--line-inner); border-radius: 10px; background: var(--surface-2); color: var(--ink); text-align: center; }
.local-cli-intro-copy { flex: 0 0 auto; display: grid; gap: 6px; justify-items: center; max-width: 46em; }
.local-cli-intro-copy b { font-size: 14px; letter-spacing: -.01em; }
.local-cli-intro-copy small { color: var(--muted); font-size: 12px; line-height: 1.65; }
.local-cli-intro-card .primary-button { margin-top: 4px; }

/* 统计卡:组合 provider-stat 复用官方用量页的卡片视觉 */
.local-cli-stats { margin-bottom: 6px; }
.local-cli-stat.tokens .stat-icon { color: var(--cyan); background: color-mix(in srgb, var(--cyan) 15%, transparent); }
.local-cli-stat.peak .stat-icon { color: var(--sky); background: color-mix(in srgb, var(--sky) 15%, transparent); }
.local-cli-stat.streak .stat-icon { color: var(--coral); background: var(--coral-bg); }
.local-cli-stat.longest .stat-icon { color: var(--violet); background: color-mix(in srgb, var(--violet) 15%, transparent); }

/* 热力图视图 */
.local-cli-heatmap-view { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.local-cli-heatmap-scroll { margin-bottom: 6px; }
/* 拖拽当日模型面板时的下限保护:热力图至少保留 130px,不会被完全挤出。
   下限写在 frame 上而不是只写内层 scroll:flex 收缩时 frame 若能被压到 0,
   内层 scroll 的 min-height 会让它向下凸出、叠到当日模型面板上 */
.local-cli-page:not(.embedded) .provider-heatmap-frame { min-height: 130px; }
.local-cli-page:not(.embedded) .local-cli-heatmap-scroll { min-height: 130px; }

/* 统计卡只在「窄且竖屏(高>宽)」的视图里收进 2×2：手机远程页、竖长桌面窗口——
   这类比例下高度富余而宽度紧张；横屏窗口（含桌面最小窗口 520×470）保持单行，
   4/5 张挤一行仍可读。第 5 张起在 2×2 模式下隐藏（2×2 只有 4 个位置） */
@media (max-width: 799px) and (orientation: portrait) {
  .provider-usage-summary { flex-wrap: wrap; }
  .provider-usage-summary > .provider-stat { flex: 1 1 calc(50% - 4px); }
  .provider-usage-summary > .provider-stat:nth-child(n+5) { display: none; }
}

/* 当日模型横向滚动区:外框高度固定,滚动条走预留轨道,溢出不改变页面布局 */
.local-cli-day-models { flex: 0 0 auto; }
.local-cli-day-models-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 0 1px 4px; }
.local-cli-day-models-title { color: var(--ink-soft); font-size: 10px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-day-models-frame { height: 88px; min-height: 88px; overflow: hidden; border: 1px solid var(--line-inner); border-radius: 8px; background: var(--surface-2); container-type: size; }
.local-cli-page.embedded .local-cli-day-models-frame { height: 36px; min-height: 36px; }
.local-cli-page.embedded .local-cli-day-models-track { padding-top: 3px; padding-bottom: 3px; }
.local-cli-page.embedded .local-cli-day-model-card { padding: 2px 7px; }
.local-cli-day-models-scroll { height: 100%; display: flex; overflow-x: auto; overflow-y: hidden; scrollbar-gutter: stable; scrollbar-width: thin; }
.local-cli-day-models-scroll::-webkit-scrollbar { height: 5px; }
.local-cli-day-models-scroll::-webkit-scrollbar-thumb { border-radius: 3px; background: var(--scrollbar); }
.local-cli-day-models-scroll::-webkit-scrollbar-track { background: transparent; }
.local-cli-day-models-scroll:focus-visible { outline: 2px solid var(--focus-border); outline-offset: -2px; }
.local-cli-day-models-track { display: flex; align-items: stretch; gap: 6px; padding: 7px 8px; height: 100%; }
.local-cli-day-model-card { flex: 0 0 auto; width: 118px; display: grid; gap: 2px; align-content: center; padding: 6px 9px; border: 1px solid var(--line-inner); border-radius: 8px; background: var(--surface-3); }
.local-cli-day-model-card-head { min-width: 0; display: flex; align-items: center; gap: 5px; }
.local-cli-day-model-card-head b { flex: 1 1 auto; min-width: 0; }
.local-cli-day-model-card-head small { flex: 0 1 auto; max-width: 48px; padding: 1px 4px; border-radius: 4px; background: var(--surface-2); }
.local-cli-day-model-card b { font-size: 10px; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-day-model-card small { font-size: 8px; color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-day-model-card em { font-style: normal; font-size: 11px; font-weight: 700; color: var(--ink-soft); }
.local-cli-models-hint { align-self: center; padding: 0 10px; color: var(--faint); font-size: 10px; white-space: nowrap; }

/* 合并同名模型开关:热力图当日区与模型拆分页共用同一状态 */
.local-cli-merge-toggle { order: 0; flex: 0 0 auto; display: inline-flex; align-items: center; gap: 5px; border: 1px solid var(--line); border-radius: 7px; padding: 3px 7px 3px 4px; color: var(--muted); background: var(--control); font-size: 9px; }
.local-cli-merge-toggle:hover { border-color: var(--hover-border); color: var(--ink-soft); }
.local-cli-merge-toggle.on { color: var(--ink); }
.local-cli-merge-toggle:focus-visible { outline: 2px solid var(--focus-border); outline-offset: 1px; }
.local-cli-merge-track { position: relative; width: 20px; height: 11px; border-radius: 20px; background: var(--toggle); transition: background .15s; }
.local-cli-merge-knob { position: absolute; top: 1.5px; left: 1.5px; width: 8px; height: 8px; border-radius: 50%; background: var(--knob); transition: transform .15s; }
.local-cli-merge-toggle.on .local-cli-merge-track { background: var(--green); }
.local-cli-merge-toggle.on .local-cli-merge-knob { transform: translateX(9px); }

/* 模型拆分视图:无统计卡,标题下直接进入数据;控件右对齐 */
.local-cli-models-view { --model-columns: minmax(116px, 1fr) minmax(110px, 1.35fr) 58px 44px; flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.local-cli-model-toolbar { flex: 0 0 auto; display: flex; align-items: center; justify-content: flex-end; gap: 8px; margin-bottom: 6px; }
.local-cli-range-total { margin-right: auto; color: var(--muted); font-size: 10px; white-space: nowrap; }
.local-cli-range-total b { color: var(--ink); font-weight: 700; }

/* 统计周期下拉:固定宽度按钮 + portal 菜单 */
.local-cli-range-select { width: 64px; height: 26px; flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: space-between; gap: 4px; padding: 0 6px 0 8px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink-soft); background: var(--control); font-size: 10px; }
.local-cli-range-select:hover { border-color: var(--hover-border); color: var(--ink); }
.local-cli-range-select svg { transition: transform .15s; flex: 0 0 auto; }
.local-cli-range-select svg.flip { transform: rotate(180deg); }
.local-cli-range-value { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-range-menu { z-index: 70; display: flex; flex-direction: column; padding: 4px; border: 1px solid var(--line-strong); border-radius: 9px; background: var(--drawer-bg); box-shadow: var(--shadow-strong); overflow: hidden; }
.local-cli-range-option { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 6px; padding: 5px 7px; border: 0; border-radius: 6px; color: var(--ink-soft); background: transparent; font-size: 10px; text-align: left; }
.local-cli-range-option:hover { background: var(--surface-3); }
.local-cli-range-option.selected { color: var(--ink); }
.local-cli-range-check { color: var(--green-deep); }
.local-cli-model-table { flex: 0 1 auto; min-height: 0; display: flex; flex-direction: column; border: 1px solid var(--line-inner); border-radius: 8px; background: var(--surface-2); overflow: hidden; }
.local-cli-model-header { flex: 0 0 auto; display: grid; grid-template-columns: var(--model-columns); gap: 8px; padding: 6px 10px; border-bottom: 1px solid var(--line-inner); color: var(--ink-soft); font-size: 9px; font-weight: 700; }
.local-cli-model-header .col-usage, .local-cli-model-header .col-cache, .local-cli-model-header .col-share { text-align: right; }
.local-cli-model-list { flex: 0 1 auto; min-height: 0; overflow-y: auto; scrollbar-gutter: stable; scrollbar-width: thin; }
.local-cli-model-list::-webkit-scrollbar { width: 5px; }
.local-cli-model-list::-webkit-scrollbar-thumb { border-radius: 3px; background: var(--scrollbar); }
.local-cli-model-list::-webkit-scrollbar-track { background: transparent; }
.local-cli-model-list:focus-visible { outline: 2px solid var(--focus-border); outline-offset: -2px; }
.local-cli-models-hint.block { display: grid; place-items: center; height: 100%; min-height: 120px; padding: 12px; text-align: center; white-space: normal; }
.local-cli-models-hint.block.error { color: var(--coral-deep); }
.local-cli-model-row { display: grid; grid-template-columns: var(--model-columns); gap: 8px; align-items: center; padding: 7px 10px; border-bottom: 1px solid var(--line-inner); }
.local-cli-model-row:last-child { border-bottom: 0; }
.local-cli-model-row .col-model { min-width: 0; display: grid; gap: 1px; }
.local-cli-model-row .col-model b { font-size: 11px; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-model-row .col-model small { font-size: 10px; color: var(--ink-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-model-row .col-usage { min-width: 0; display: grid; grid-template-columns: minmax(0, 1fr) 68px; align-items: center; gap: 10px; }
.local-cli-model-row .col-bar { min-width: 0; }
.local-cli-total-bar { display: block; height: 10px; min-width: 0; border-radius: 4px; background: linear-gradient(90deg, color-mix(in srgb, var(--cyan) 65%, transparent), var(--cyan)); }
.local-cli-model-row .col-total { font-size: 11px; font-weight: 700; color: var(--ink); text-align: right; white-space: nowrap; }
.local-cli-model-row .col-cache { font-size: 11px; color: var(--ink-soft); text-align: right; white-space: nowrap; }
.local-cli-model-row .col-share { font-size: 11px; color: var(--ink-soft); text-align: right; white-space: nowrap; }

@media (min-width: 800px) {
  .local-cli-models-view { --model-columns: clamp(170px, 22vw, 240px) minmax(160px, 1fr) 84px 64px; }
  .local-cli-model-header { padding: 9px 14px; font-size: 11px; }
  .local-cli-model-row { padding: 8px 14px; }
  .local-cli-model-row .col-usage { grid-template-columns: minmax(0, 1fr) 88px; gap: 16px; }
  .local-cli-model-row .col-model b, .local-cli-model-row .col-total, .local-cli-model-row .col-cache, .local-cli-model-row .col-share { font-size: 13px; }
}

/* 渠道单选下拉:固定宽度按钮 + portal 菜单 */
.local-cli-channel-select { width: 96px; height: 26px; flex: 0 0 96px; display: inline-flex; align-items: center; justify-content: space-between; gap: 4px; padding: 0 6px 0 8px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink-soft); background: var(--control); font-size: 10px; }
.local-cli-channel-select:hover { border-color: var(--hover-border); color: var(--ink); }
.local-cli-channel-select svg { transition: transform .15s; flex: 0 0 auto; }
.local-cli-channel-select svg.flip { transform: rotate(180deg); }
.local-cli-channel-value { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-channel-menu { z-index: 70; display: flex; flex-direction: column; border: 1px solid var(--line-strong); border-radius: 9px; background: var(--drawer-bg); box-shadow: var(--shadow-strong); overflow: hidden; }
.local-cli-channel-search { display: flex; align-items: center; gap: 5px; padding: 6px 8px; border-bottom: 1px solid var(--line-inner); color: var(--faint); }
.local-cli-channel-search input { flex: 1 1 auto; min-width: 0; border: 0; background: transparent; color: var(--ink); font-size: 10px; outline: none; }
.local-cli-channel-options { max-height: 208px; overflow-y: auto; scrollbar-width: thin; padding: 4px; }
.local-cli-channel-option { width: 100%; display: flex; align-items: center; gap: 6px; padding: 5px 7px; border: 0; border-radius: 6px; color: var(--ink-soft); background: transparent; font-size: 10px; text-align: left; }
.local-cli-channel-option.active { background: var(--surface-3); }
.local-cli-channel-option.selected { color: var(--ink); }
.local-cli-channel-option:disabled { opacity: .48; cursor: not-allowed; background: transparent; }
.local-cli-channel-option:disabled:hover { background: transparent; }
.local-cli-channel-option > small { flex: 0 0 auto; color: var(--faint); font-size: 8px; }
.local-cli-channel-name { flex: 1 1 auto; min-width: 0; display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-cli-channel-name i { width: 6px; height: 6px; border-radius: 50%; flex: 0 0 auto; }
.local-cli-channel-check { color: var(--green-deep); }
.local-cli-channel-empty { padding: 10px; color: var(--faint); font-size: 10px; text-align: center; }

/* ── 首次使用引导向导 ── */
.onboard-shell { height: 100%; box-sizing: border-box; display: flex; align-items: center; justify-content: center; overflow: hidden; animation: fade-in .3s ease-out; }
/* 引导页独占整块内容区：去掉主区留白，把可用高度全部让给卡片 */
.main-shell:has(> .content-area > .onboard-shell) { padding: 4px 6px 6px; }
.content-area:has(> .onboard-shell) { height: 100%; padding-top: 0; }
/* 卡片尺寸锁死：宽 520、高 400–420，四步（含接入步的两个状态）完全一致，绝不随内容变化 */
.onboard-card { width: min(520px, 100%); height: 420px; max-width: 100%; max-height: 100%; display: flex; flex-direction: column; padding: 40px; border: 1px solid var(--line); border-radius: 18px; background: var(--surface-trans); box-shadow: var(--shadow); backdrop-filter: blur(10px); animation: rise-in .28s ease-out; box-sizing: border-box; }
/* 顶部区域：进度条 + 标题 + 副标题，固定不浮动 */
.onboard-head { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; padding-top: 4px; }
.onboard-head h1, .onboard-group h1 { margin: 0; font-size: 20px; line-height: 1.3; letter-spacing: -.03em; text-align: center; }
.onboard-head .onboard-sub { margin: 8px 0 0; }
.onboard-sub { max-width: 440px; color: var(--muted); font-size: 13px; line-height: 1.5; text-align: center; }
.onboard-steps { flex: 0 0 auto; display: flex; justify-content: center; align-items: center; gap: 6px; width: 100%; height: 8px; margin-bottom: 18px; }
.onboard-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--line-strong); transition: .2s; }
.onboard-dot.past { background: var(--green); }
.onboard-dot.active { background: var(--green); width: 20px; border-radius: 4px; }
/* 中间区域：自适应撑开，内容垂直水平居中 */
.onboard-body { flex: 1 1 auto; min-height: 0; display: flex; align-items: center; justify-content: center; width: 100%; overflow: hidden; }
/* 接入步：三区骨架中的中间区，纵向排布并垂直居中；卡片高度固定，底部按钮永不被顶走 */
/* 接入步：中部区拆成「固定展示区 + 添加入口」两段，展示区吃掉剩余高度（6 格网格刚好放满） */
.onboard-body.is-connect { flex-direction: column; align-items: stretch; justify-content: flex-start; padding-top: 2px; }
/* 导入步：左右两栏。左侧是能导入的账号清单（占主要空间），右侧是导入按钮与无法导入的原因 */
.onboard-body.is-ccswitch { flex-direction: row; align-items: center; justify-content: stretch; gap: 12px; min-height: 0; padding: 6px 0; }
.onboard-import { flex: 0 1 auto; min-height: 0; max-height: 172px; display: flex; align-items: stretch; gap: 14px; width: 100%; }
.onboard-import-main { flex: 1 1 auto; min-width: 0; min-height: 0; max-height: 172px; display: flex; }
/* 左侧清单：可勾选、可滚动，滚动条内嵌且低调 */
.onboard-scan-list { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; gap: 8px; width: 100%; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; padding-right: 2px; }
.onboard-scan-list::-webkit-scrollbar { width: 4px; }
.onboard-scan-list::-webkit-scrollbar-thumb { border-radius: 2px; background: rgba(150, 160, 158, .22); }
.onboard-scan-list::-webkit-scrollbar-thumb:hover { background: rgba(150, 160, 158, .5); }
.onboard-scan-list::-webkit-scrollbar-track { background: transparent; }
.onboard-scan-row { display: flex; align-items: center; gap: 10px; height: 52px; min-height: 52px; padding: 0 12px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface-2); cursor: pointer; box-sizing: border-box; }
.onboard-scan-row:hover { border-color: var(--hover-border); }
.onboard-scan-row input { flex: 0 0 auto; width: 13px; height: 13px; margin: 0; accent-color: var(--green); }
.onboard-scan-copy { flex: 1; min-width: 0; display: grid; gap: 2px; }
.onboard-scan-copy b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }
.onboard-scan-copy small { color: var(--faint); font-size: 10px; }
.onboard-scan-ok { flex: 0 0 auto; color: var(--green); }
/* 左侧空态 / 读取中：始终有内容可看，不留空白 */
.onboard-import-hint { flex: 1 1 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; min-height: 0; padding: 16px; border: 1px dashed color-mix(in srgb, var(--faint) 45%, transparent); border-radius: 10px; color: var(--muted); text-align: center; box-sizing: border-box; }
.onboard-import-hint svg { color: var(--faint); }
.onboard-import-hint b { font-size: 12px; font-weight: 600; color: var(--ink-soft); }
.onboard-import-hint span { font-size: 10px; line-height: 1.5; }
/* 右侧：导入按钮在上，无法导入的条目在下（只列前 3 条，完整原因悬停可见） */
.onboard-import-side { flex: 0 0 auto; width: 172px; display: flex; flex-direction: column; justify-content: center; gap: 10px; min-height: 0; }
.onboard-import-go { flex: 0 0 auto; width: 100%; padding: 9px 12px; font-size: 12px; font-weight: 700; }
.onboard-import-blocked { flex: 0 0 auto; max-height: 96px; min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 9px 11px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface-2); overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.onboard-import-blocked-title { color: var(--faint); font-size: 10px; }
.onboard-blocked-row { display: flex; align-items: center; gap: 5px; min-width: 0; color: var(--muted); font-size: 10px; }
.onboard-blocked-row svg { flex: 0 0 auto; color: var(--coral); }
.onboard-blocked-row b { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
.onboard-blocked-row small { flex: 0 0 auto; color: var(--faint); font-size: 9px; white-space: nowrap; }
.onboard-blocked-row.is-more { cursor: help; }
.onboard-blocked-row.is-more small { color: var(--hover-border); }
.onboard-scan-error { flex: 1 1 auto; display: flex; align-items: center; gap: 8px; padding: 10px 12px; border: 1px solid var(--warn-border); border-radius: 10px; color: var(--coral-deep); background: var(--coral-bg); font-size: 11px; }
/* 图1 / 图4：图标 + 标题 + 副标题 + 按钮作为一个 group 整体居中，间距依次 24 / 8 / 32 */
.onboard-body.is-hero { justify-content: center; padding-bottom: 26px; }
.onboard-group { display: flex; flex-direction: column; align-items: center; width: 100%; }
/* 两页的图标外框都是 80×80，欢迎页是圆角方图、完成页是圆形对勾 + 光环，按钮落点因此完全一致 */
.onboard-hero { width: 80px; height: 80px; display: grid; place-items: center; margin-bottom: 24px; }
.onboard-hero img { width: 80px; height: 80px; border-radius: 20px; box-shadow: 0 12px 28px rgba(63, 179, 132, .28); }
.onboard-hero-done span { width: 66px; height: 66px; display: grid; place-items: center; border-radius: 50%; color: var(--green); background: var(--green-bg); box-shadow: 0 0 0 7px var(--green-bg-2); }
.onboard-group .onboard-sub { margin: 8px 0 0; }
.onboard-cta { margin-top: 32px; }
/* 底部区域：按钮组，固定距底，margin-top:auto 推到底部 */
.onboard-foot { flex: 0 0 auto; display: flex; justify-content: center; align-items: center; gap: 14px; margin-top: auto; padding-top: 8px; }
.onboard-foot .primary-button, .onboard-foot .outline-button, .onboard-cta, .onboard-import-go { display: inline-flex; justify-content: center; align-items: center; min-width: 100px; padding: 8px 18px; font-size: 12px; border-radius: 9px; }
.onboard-foot .primary-button, .onboard-cta, .onboard-import-go { color: #0f1a15; background: var(--green); border-color: transparent; font-weight: 700; }
.onboard-foot .primary-button:hover, .onboard-cta:hover, .onboard-import-go:hover { filter: brightness(1.1); color: #0f1a15; }
.onboard-theme-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; width: 100%; }
.onboard-theme-card { position: relative; display: grid; gap: 4px; justify-items: center; padding: 13px 12px 11px; border: 1px solid var(--line); border-radius: 13px; background: var(--surface-2); color: var(--ink); transition: border-color .16s, box-shadow .16s, transform .16s; }
.onboard-theme-card:hover { border-color: var(--hover-border); transform: translateY(-1px); }
.onboard-theme-card.selected { border-color: var(--focus-border); box-shadow: 0 0 0 3px var(--focus-ring); }
.onboard-theme-card b { font-size: 12px; }
.onboard-theme-card small { color: var(--faint); font-size: 9px; }
.onboard-theme-preview { width: 100%; height: 52px; display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 5px; padding: 7px; border-radius: 8px; margin-bottom: 3px; }
.onboard-theme-preview i { border-radius: 5px; display: block; }
.preview-dark { background: #141d1f; box-shadow: inset 0 0 0 1px #2c393b; }
.preview-dark i { background: #263334; }
.preview-dark i:first-child { background: #3fb384; opacity: .85; }
.preview-light { background: #f3f5f1; box-shadow: inset 0 0 0 1px #dfe4df; }
.preview-light i { background: #ffffff; box-shadow: 0 1px 3px rgba(50, 66, 61, .12); }
.preview-light i:first-child { background: #2e8b66; opacity: .85; }
.onboard-theme-check { position: absolute; top: 9px; right: 9px; width: 21px; height: 21px; display: grid; place-items: center; border-radius: 50%; color: #fff; background: var(--green); }
/* ── 接入步展示区 ── 有/无账号共用的固定尺寸区域，内容垂直水平居中、永不滚动 */
.onboard-slots { flex: 1 1 auto; min-height: 0; width: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; overflow: hidden; }
.onboard-slots-bar { flex: 0 0 auto; display: flex; justify-content: flex-end; width: 100%; }
/* 手动添加入口：账号信息区右上角的轻量图标，风格与周边的细线一致 */
.onboard-slots-add { width: 26px; height: 26px; display: grid; place-items: center; padding: 0; border: 1px solid var(--line); border-radius: 7px; background: transparent; color: var(--muted); transition: border-color .16s, color .16s, background .16s; }
.onboard-slots-add:hover { border-color: var(--hover-border); color: var(--ink); background: var(--surface-2); }
/* 无账号：90px 轻量占位，虚线更浅、文字更醒目 */
.onboard-empty { width: 100%; height: 90px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; color: var(--ink-soft); border: 1px dashed var(--onboard-dash); border-radius: 10px; box-sizing: border-box; }
.onboard-empty svg { color: var(--faint); opacity: .5; }
.onboard-empty span { font-size: 12px; }
/* 有账号：双列网格，每格 64px；容器最高 140px，账号更多时在内部平滑滚动，滚动条 4px 极浅 */
.onboard-grid { display: grid; grid-template-columns: 1fr 1fr; grid-auto-rows: 64px; gap: 12px; width: 100%; max-height: 140px; overflow-y: auto; overscroll-behavior: contain; padding-right: 2px; box-sizing: border-box; }
.onboard-grid::-webkit-scrollbar { width: 4px; }
.onboard-grid::-webkit-scrollbar-thumb { border-radius: 2px; background: rgba(150, 160, 158, .22); }
.onboard-grid::-webkit-scrollbar-thumb:hover { background: rgba(150, 160, 158, .5); }
.onboard-grid::-webkit-scrollbar-track { background: transparent; }
.onboard-cell { display: flex; align-items: center; gap: 9px; height: 64px; min-width: 0; padding: 0 12px; border-radius: 8px; background: var(--onboard-tile); box-sizing: border-box; }
/* 厂商图标只留 24px 图形本身，不带背景框 */
.onboard-cell .provider-logo, .onboard-cell .provider-logo.sm { width: 24px; height: 24px; border-radius: 6px; font-size: 11px; background: none; box-shadow: none; }
.onboard-cell b { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 600; }
/* 右侧：默认是状态圆点，悬停整格时平滑换成垃圾桶（淡灰 → 悬停变红） */
.onboard-cell-remove { flex: 0 0 auto; width: 22px; height: 22px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 6px; background: transparent; }
.onboard-cell-remove .onboard-cell-dot, .onboard-cell-remove svg { grid-area: 1 / 1; transition: opacity .16s, color .16s; }
.onboard-cell-remove svg { opacity: 0; color: var(--faint); }
.onboard-cell-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); }
.onboard-cell-dot.off { background: var(--faint); }
.onboard-cell:hover .onboard-cell-dot { opacity: 0; }
.onboard-cell:hover .onboard-cell-remove svg { opacity: 1; }
.onboard-cell-remove:hover svg { color: var(--coral-deep); }
.onboard-cell-remove:hover { background: var(--coral-bg); }
/* 中下部：接入步只留一个图标式手动添加入口（cc-switch 已在上一步单独引导） */

/* cc-switch 引导步：三条说明 + 开始导入 */
.onboard-body.is-ccswitch { flex-direction: column; align-items: stretch; justify-content: center; gap: 14px; }

@media (max-width: 620px) {
  .onboard-theme-preview { height: 44px; }
}
/* 极窄窗口才收水平留白，正常 520 主窗口保持 40px 四边内边距 */
@media (max-width: 470px) {
  .onboard-card { padding: 40px 18px; }
  .onboard-theme-grid { grid-template-columns: 1fr; }
}

/* 局域网远程查看与二维码配对 */
.drawer-help { display: block; color: var(--ink-soft); font-size: 13px; line-height: 1.55; }
.remote-setting { display: grid; gap: 9px; }
.remote-setting-port-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; }
.remote-setting-port { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-width: 0; padding: 5px 0; }
.remote-setting-port > span { min-width: 0; display: grid; gap: 3px; }
.remote-setting-port b { font-size: 11px; font-weight: 650; }
.remote-setting-port small { color: var(--faint); font-size: 9px; line-height: 1.4; }
.remote-setting-port input { width: 76px; height: 30px; padding: 0 7px; border: 1px solid var(--line); border-radius: 6px; color: var(--ink); background: var(--control); font-size: 11px; }
.remote-port-save { min-width: 48px; min-height: 29px; padding: 5px 9px; font-size: 10px; }
.remote-qr-button { min-height: 36px; }
.remote-setting-status { display: flex; align-items: center; gap: 7px; padding: 8px 9px; border-radius: 7px; font-size: 10px; }
.remote-setting-status i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.remote-setting-status.ok { color: var(--green-deep); background: var(--green-bg); }
.remote-setting-status.fail, .remote-setting-error { color: var(--coral-deep); }
