.remote-mobile-download { color: var(--muted); font-size: 10px; line-height: 1.5; }
.remote-mobile-download a { color: var(--green-deep); text-decoration: underline; text-underline-offset: 2px; }
.remote-setting-actions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
