.remote-qr-modal .remote-paired-device { padding: 7px 2px; }
.remote-qr-copy { min-height: 33px; padding: 7px; font-size: 10px; }
.remote-qr-reset { justify-self: center; padding: 4px 8px; }
.remote-qr-reset-confirm { display: grid; gap: 5px; color: var(--muted); font-size: 9px; text-align: center; }
.remote-qr-reset-confirm > div { display: flex; justify-content: center; gap: 7px; }
.remote-qr-reset-confirm button { min-height: 26px; padding: 4px 9px; border: 0; border-radius: 5px; font-size: 9px; }
.remote-qr-reset-danger { color: var(--coral-deep); background: var(--coral-bg); }
.remote-qr-reset-cancel { color: var(--ink-soft); background: var(--control); }
.remote-title-action { width: 25px; height: 23px; display: grid; place-items: center; flex: 0 0 auto; padding: 0; border: 1px solid var(--line); border-radius: 6px; color: var(--ink-soft); background: var(--control); }
.remote-title-action:hover, .remote-title-action.active { color: var(--green-deep); border-color: var(--hover-border); background: var(--green-bg); }
.remote-settings-page { width: min(100%, 760px); margin: 0 auto; }
.remote-settings-card { display: grid; gap: 13px; padding: 15px; margin: 0 0 11px; border: 1px solid var(--line); border-radius: 11px; background: var(--surface); box-shadow: var(--shadow); }
.remote-settings-card-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.remote-settings-card-head > b { font-size: 13px; }
.remote-settings-card-head > small { color: var(--faint); font-size: 10px; }
.remote-settings-section { display: grid; grid-template-columns: 88px minmax(0, 1fr); align-items: center; gap: 10px; }
.remote-settings-section > span { color: var(--muted); font-size: 11px; }
.remote-setting-options { display: flex; flex-wrap: wrap; gap: 7px; }
.remote-setting-options button { min-height: 34px; display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink-soft); background: var(--control); font-size: 10px; }
.remote-setting-options button.active { border-color: var(--focus-border); color: var(--green-deep); background: var(--green-bg); }
.remote-settings-access p { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.6; }
.remote-interactive-badge { padding: 4px 7px; border-radius: 5px; color: var(--green-deep); background: var(--green-bg); font-size: 9px; white-space: nowrap; }
.shared-settings-page { display: grid; gap: 0; width: min(100%, 760px); margin: 0 auto; }
.shared-settings-page .remote-settings-card { min-width: 0; }
.remote-settings-toggle, .remote-settings-field { display: flex; align-items: center; justify-content: space-between; gap: 14px; min-width: 0; padding: 8px 0; }
.remote-settings-toggle > span, .remote-settings-field > span, .remote-settings-rule-heading > span { display: grid; gap: 4px; min-width: 0; }
.remote-settings-toggle b, .remote-settings-field b, .remote-settings-rule-heading b { color: var(--ink-soft); font-size: 11px; font-weight: 600; }
.remote-settings-toggle small, .remote-settings-field small, .remote-settings-rule-heading small { color: var(--faint); font-size: 9px; line-height: 1.45; }
.remote-settings-toggle input { width: 18px; height: 18px; flex: 0 0 auto; accent-color: var(--green); }
.remote-settings-field select { min-width: 115px; max-width: 55%; height: 34px; padding: 0 8px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink-soft); background: var(--control); font-size: 10px; }
.remote-settings-rule-heading { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 10px; border-top: 1px solid var(--line-inner); }
.remote-settings-rule { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 28px; align-items: end; gap: 8px; padding: 9px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface-2); }
.remote-settings-rule label { display: grid; gap: 5px; min-width: 0; color: var(--faint); font-size: 9px; }
.remote-settings-rule input { width: 100%; min-width: 0; height: 32px; padding: 0 7px; border: 1px solid var(--line); border-radius: 6px; color: var(--ink); background: var(--control); font-size: 11px; }
.remote-settings-rule .icon-button { width: 28px; height: 28px; }
.remote-settings-empty { padding: 12px 8px; border-radius: 7px; color: var(--faint); background: var(--surface-2); text-align: center; font-size: 10px; }
.remote-settings-savebar { position: sticky; bottom: 0; z-index: 2; display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 8px -2px 0; padding: 9px 2px max(9px, env(safe-area-inset-bottom)); background: linear-gradient(180deg, transparent, var(--bg) 18%); }
.remote-settings-savebar > span { color: var(--faint); font-size: 9px; }
.remote-settings-savebar > span.saved { color: var(--green-deep); }
.remote-settings-savebar > span.error { color: var(--coral-deep); }
.remote-settings-savebar .primary-button { min-height: 36px; padding: 8px 13px; white-space: nowrap; }
.remote-paired-devices { display: grid; gap: 5px; margin: 13px 0 5px; padding: 10px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface-2); }
.remote-paired-devices-head, .remote-paired-device { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-width: 0; }
.remote-paired-devices-head { padding: 0 2px 5px; color: var(--faint); font-size: 9px; }
.remote-paired-devices-head > span:first-child, .remote-paired-device > span { display: grid; gap: 3px; min-width: 0; }
.remote-paired-devices-head b, .remote-paired-device b { overflow: hidden; color: var(--ink-soft); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.remote-paired-devices-head small, .remote-paired-device small { overflow: hidden; color: var(--faint); font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
.remote-paired-device { padding: 6px 2px; border-top: 1px solid var(--line-inner); }
.remote-paired-device > span { flex: 1; }
.remote-setting-lan-select { width: 100%; gap: 6px; padding: 7px 0; text-align: left; }
.remote-setting-lan-select select { max-width: 145px; overflow: hidden; text-overflow: ellipsis; }
.remote-setting-confirm { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; color: var(--muted); font-size: 9px; }
.remote-setting-confirm span { flex: 1 1 100%; }
.remote-setting-confirm button, .remote-setting-link { padding: 5px 7px; border: 0; border-radius: 5px; color: var(--coral-deep); background: var(--coral-bg); font-size: 9px; }
.remote-setting-link { justify-self: start; background: transparent; }
.remote-setting-link:hover { background: var(--coral-bg); }

/* ── 可调整主窗口：从 520px 工具窗平滑扩展到桌面工作台 ── */
/* 小窗沿用原始密度；宽度增加后卡片只增长到舒适阅读宽度，余量用于更多列和均衡留白。 */
@media (min-width: 800px) {
  .overview-grid { gap: 12px; }
  .overview-grid > .overview-card { flex-basis: calc(100% / 3 - 9px); max-width: min(286px, calc(100% / 3 - 9px)); }
  .overview-card { min-height: 208px; padding: 11px; }
  .overview-body { gap: 14px; padding: 10px 1px 5px; }
  .concentric-rings { width: 94px; height: 94px; }
  .overview-meters { gap: 8px; }

  .settings-drawer { width: min(440px, calc(100vw - 48px)); }
  .drawer-scroll { padding-right: 20px; padding-left: 20px; }
  .drawer-header { padding-right: 20px; padding-left: 20px; }

  .modal:not(.compact-modal) { width: min(520px, 100%); }
  .provider-modal { width: min(620px, 100%); }

  .windows-column-head { grid-template-columns: minmax(210px, 320px) minmax(0, 1fr) 100px; }
  .account-window-row { grid-template-columns: minmax(210px, 320px) minmax(0, 1fr); min-height: 96px; padding-right: 16px; padding-left: 16px; }
  .meter-line { grid-template-columns: 44px minmax(100px, 1fr) 120px 104px; gap: 8px; }
  .priority-row { grid-template-columns: minmax(210px, 320px) minmax(180px, 1fr) 150px; height: 64px; padding-right: 16px; padding-left: 16px; }
  .priority-reset .rule-marks .tag-pill { max-width: 68px; }
  .timeline-track { min-width: 100%; }
}

/* 账号详情页面板高度链（桌面端，.app-shell 作用域——远程页在 remote.css 里有
   覆盖所有宽度的同款链）：改为弹性填充。面板吃满窗口剩余高度（不小于 271px），
   「返回」按钮贴底，余量不再堆在页面底部形成大片空白；此前固定高度公式
   (100vh - 210px) 在小窗口低于 271px 下限，在大窗口也低估可用高度 */
.app-shell .view-stack.history-view { display: flex; flex-direction: column; }
/* 详情页在位时让滚动容器变成 flex 高度链（同本机用量页 local-usage-mode 的做法）：
   视图精确吃满剩余高度，不需要按断点估算镶边，任何窗口尺寸都不会溢出或留底部空白 */
.main-shell:has(> .content-area > .history-view) { display: flex; flex-direction: column; overflow: hidden; }
.main-shell:has(> .content-area > .history-view) > .content-area { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.main-shell:has(> .content-area > .history-view) > .content-area > .history-view { flex: 1 1 auto; min-height: 0; }
.app-shell .history-view > .surface-section { flex: 1 1 auto; display: flex; flex-direction: column; min-height: 0; }
.app-shell .history-view .history-head { flex: 0 0 auto; }
.app-shell .history-view .history-tabpanel { flex: 1 1 auto; display: flex; flex-direction: column; min-height: 0; }
.app-shell .history-view .trend-view,
.app-shell .history-view .waste-view,
.app-shell .history-view .local-cli-page.embedded { flex: 1 1 auto; height: auto; min-height: 271px; }
/* 用量视图面板独立上限：格子有尺寸封顶(40×96)，超过格网能吃满的高度后只会
   在框内留白；收到 ~960px 让面板"格网吃满即止"，更高的窗口把余量留给页面背景 */
.app-shell .history-view .provider-usage-view { flex: 1 1 auto; height: auto; min-height: 271px; max-height: 960px; }
/* 连接引导/加载/错误等状态视图不跟随面板拉伸：内容只有一两百像素，保持紧凑居中 */
.app-shell .history-view .provider-usage-state { height: 271px; }
/* 连接提示在现有面板内居中，不改变账号栏、外框和底部返回入口。 */
.app-shell .history-view .provider-usage-state.connect-guide { flex: 1 1 auto; height: auto; min-height: 0; overflow-y: auto; }
/* svg 高度按宽度等比取整后可能比容器高出 1-2px 零头，overflow hidden 吸收，
   避免把整页顶出滚动条 */
.trend-view > .usage-chart { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.trend-view > .usage-chart > svg { flex: 0 0 auto; }

/* 引导页：宽屏时卡片从容撑开，不再锁死 520×420 */
@media (min-width: 800px) {
  .onboard-card { width: min(640px, calc(100vw - 48px)); height: min(520px, calc(100vh - 48px)); padding: 48px; }
  .onboard-head h1, .onboard-group h1 { font-size: 24px; }
  .onboard-sub { font-size: 14px; }
  .onboard-hero, .onboard-hero img { width: 92px; height: 92px; }
  .onboard-hero img { border-radius: 23px; }
  .onboard-scan-row { height: 58px; min-height: 58px; }
}
@media (min-width: 1200px) {
  .onboard-card { width: min(720px, calc(100vw - 96px)); height: min(560px, calc(100vh - 64px)); }
  .onboard-head h1, .onboard-group h1 { font-size: 27px; }
  .onboard-import-main, .onboard-import { max-height: 220px; }
  .onboard-import-side { width: 196px; }
}

/* 多标签头部：宽屏下标签居中并放宽间距，避免整排挤在左侧 */
@media (min-width: 1200px) {
