  .overview-grid > .overview-card { flex: 1 1 calc(25% - 13px); max-width: calc(25% - 13px); }
  .overview-card { min-height: 240px; padding: 14px; }
  .overview-body { gap: 18px; padding-top: 12px; }
  .concentric-rings { width: 110px; height: 110px; }
  .quota-ring { inset: calc(var(--ring-index, 0) * 10px); }
  .quota-ring span { inset: 7px; }
  .ring-core { inset: 33px; }
  .ring-core strong { max-width: 73px; font-size: 12px; }
  .ring-core small { font-size: 9px; }
  .overview-meters { gap: 10px; }
  .overview-meter span { font-size: 11px; }
  .overview-meter b { font-size: 13.5px; }
  .overview-meter small { font-size: 11px; }
  .overview-card .account-title-line strong { font-size: 13px; }
  .overview-card .account-copy > span { font-size: 10.5px; }
  .overview-card .provider-logo { width: 32px; height: 32px; }
