  .overview-body { gap: 22px; padding-top: 16px; }
  .concentric-rings { width: 128px; height: 128px; }
  .quota-ring { inset: calc(var(--ring-index, 0) * 12px); }
  .quota-ring span { inset: 8px; }
  .ring-core { inset: 38px; }
  .ring-core strong { max-width: 85px; font-size: 13.5px; }
  .ring-core small { font-size: 9.5px; }
  .overview-meters { gap: 12px; }
  .overview-meter span { font-size: 12px; }
  .overview-meter b { font-size: 15px; }
  .overview-meter small { font-size: 11.5px; }
  .overview-card .account-title-line strong { font-size: 14px; }
  .overview-card .account-copy > span { font-size: 11px; }
  .overview-card .provider-logo { width: 34px; height: 34px; }
  .overview-card .card-status-icon { width: 22px; height: 22px; }
}

@media (min-width: 1900px) {
  .refresh-bar { height: 42px; gap: 12px; }
  .refresh-track { gap: 12px; }
  .refresh-bar-title { font-size: 12px; }
  .refresh-chip { font-size: 12px; max-width: 220px; padding: 5px 13px; }
  .refresh-chip em, .refresh-chip small, .refresh-chip b { font-size: 11px; }
