  .overview-body { gap: 26px; padding-top: 20px; }
  .concentric-rings { width: 146px; height: 146px; }
  .quota-ring { inset: calc(var(--ring-index, 0) * 14px); }
  .quota-ring span { inset: 9px; }
  .ring-core { inset: 44px; }
  .ring-core strong { max-width: 97px; font-size: 15px; }
  .ring-core small { font-size: 10px; }
  .overview-meters { gap: 14px; }
  .overview-meter span { font-size: 12.5px; }
  .overview-meter b { font-size: 16.5px; }
  .overview-meter small { font-size: 12px; }
  .overview-card .account-title-line strong { font-size: 15px; }
  .overview-card .account-copy > span { font-size: 11.5px; }
