/* 账号少时整组卡片在可视区内垂直居中，不再贴顶留一片空 */
@media (min-width: 800px) and (min-height: 640px) {
  .view-stack:has(> .overview-grid) { min-height: calc(100vh - 150px); align-content: center; }
}

.trend-view > .chart-empty { flex: 1 1 auto; display: grid; place-items: center; padding: 24px; }

/* ── 详情页宽屏放大：统计数字、热力图标签、图表坐标轴、当日模型条一起跟随放大 ── */
@media (min-width: 1500px) {
  .history-head { padding: 15px 20px 12px; }
  .history-head .account-title-line strong { font-size: 15px; }
  .history-head .account-copy > span { font-size: 11.5px; }
  .history-view .seg-control button, .local-cli-page .seg-control button, .history-view .history-switch-toggle { padding: 5px 14px; font-size: 12px; }
