}

/* 垂直拖拽分隔条:本机用量、额度浪费共用;静止时只是一条细线,悬停/拖拽才放大 */
.resize-handle { flex: 0 0 auto; height: 10px; margin: -3px 0; display: grid; place-items: center; cursor: row-resize; touch-action: none; border-radius: 5px; position: relative; z-index: 2; }
.resize-handle i { width: 32px; height: 3px; border-radius: 2px; background: var(--ink-soft); opacity: .7; transition: width .15s, height .15s, background .15s, opacity .15s; }
.resize-handle:hover i, .resize-handle.dragging i, .resize-handle:focus-visible i { width: 54px; height: 3px; background: var(--green); opacity: 1; }
.resize-handle:focus-visible { outline: 2px solid var(--focus-border); outline-offset: -1px; }
body.row-resizing, body.row-resizing * { cursor: row-resize !important; user-select: none !important; }

/* 当日模型面板被拖高后,卡片随容器高度逐级放大(尺寸与字号),充分利用纵向空间;
   放在宽屏断点之后,保证面板拉高时容器查询覆盖断点的固定卡片尺寸 */
